(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ms"] = {"ui":{"skip":"Langkau ke kandungan","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tiada bahasa yang sepadan","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Tukar tema: cerah, gelap atau hitam","theme.toLight":"Tukar ke tema cerah","theme.toDark":"Tukar ke tema gelap","theme.toBlack":"Tukar ke tema hitam (hitam sebenar, mesra skrin OLED)","words.underline":"Gariskan perkataan ini pada halaman","words.underlineHelp":"Tuding atau ketik perkataan bergaris titik untuk melihat maksudnya.","words.col.todo":"Kad yang dipilih untuk sekarang: pasukan akan mula dengan kad ini seterusnya.","words.col.doing":"Satu AI sedang mengerjakan kad ini sekarang.","words.col.review":"Satu AI sudah siap kerja; satu lagi menyemaknya sebelum sampai kepada anda.","words.col.verify":"Menunggu anda: cuba dan beritahu sama ada ia berfungsi.","words.col.team":"Nota atau jawapan anda, menunggu pasukan mengambilnya.","words.col.done":"Siap dan diterima.","index.title":"AI-gile: pasukan pembangunan AI anda, dalam satu papan","index.description":"AI-gile ialah papan kanban untuk pasukan pengekodan AI. Mereka bekerja semasa anda tidur; anda mendapat satu longgokan pendek: apa yang perlu diputuskan, diuji dan diterima.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Pasukan pembangunan AI anda, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum siap: terima kasih kerana mencuba!","hero.lede":"Mereka membina semasa anda tidur. Anda bangun dengan satu longgokan pendek: beberapa soalan, beberapa perkara untuk diuji, satu dua berlian ungu. Klik, terima, kembali ke kopi anda.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan dalam pelayar anda","dl.messenger":"📱 Messenger untuk telefon anda","dl.soon":"Akan datang","dl.notify":"🔔 Beritahu saya bila ia dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tetapi pasukan ini tidak pernah perlukan kopi stand-up. (Mereka tetap buat stand-up.)","pitch.h2":"AI-gile dalam seberapa banyak perkataan yang anda mahu","pitch.lede":"Pilih panjang, dari satu perkataan hingga 144. Setiap panjang ialah penerangan tersendiri, ditulis untuk saiz itu. Seret peluncur atau guna kekunci anak panah.","pitch.rangeLabel":"Panjang dalam perkataan","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} perkataan","pitch.words.other":"{n} perkataan","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} aksara","pitch.chars.other":"{n} aksara","count.line.html.one":"{n} kad pada papan sekarang","count.line.html.other":"{n} kad pada papan sekarang","people.humans.html.one":"👥 {n} manusia","people.humans.html.other":"👥 {n} manusia","people.agents.html.one":"🤖 {n} ejen","people.agents.html.other":"🤖 {n} ejen","people.working.html.one":"⚡ {n} sedang bekerja sekarang","people.working.html.other":"⚡ {n} sedang bekerja sekarang","pre.title":"AI-gile: sesuatu sedang dibina","pre.description":"Sesuatu sedang dibina di sini: papan tempat pasukan AI membina apa yang anda minta, dan mengajar anda sambil itu. Buat masa ini pra-alfa tertutup bersama kawan-kawan.","pre.h1":"Sesuatu sedang dibina di sini. 🤫","pre.line":"Papan tempat pasukan AI membina apa yang anda minta, dan mengajar anda sambil itu. Buat masa ini pra-alfa tertutup bersama kawan-kawan.","pre.btn":"🔔 Beritahu saya bila ia dibuka","pre.peek":"Di sebalik kaca: papan sebenar, secara langsung. Setiap kad ialah satu jalur berwarna.","pre.peekFake":"Di sebalik kaca: beginilah rupa papan yang sedang bekerja.","pre.night":"🌙 Pengawal malam yang bertugas · 😴 manusia sedang berehat","features.aria":"Apa yang ia lakukan","f.pile.h":"Satu longgokan untuk anda","f.pile.html":"<b>Untuk anda</b> mengumpulkan semua yang menunggu anda, merentas setiap projek: soalan, perkara untuk diuji, tugas yang hanya manusia boleh buat. Giliran anda memberitahu apa yang seterusnya dan berapa lama ia mengambil masa.","f.sleep.h":"Pasukan yang bekerja semasa anda tidur","f.sleep.p":"Setiap projek ada seorang ketua dan pasukan ejen AI. Beri komen pada kad dan pasukan itu bangun, menyiapkan kerja, lalu menyerahkannya semula dengan langkah yang boleh diikuti oleh manusia yang penat.","f.tester.h":"Penguji AI menyemak dahulu","f.tester.p":"Sebelum apa-apa sampai kepada anda, seorang penguji mengikut langkah dalam salinan aplikasi dan menunjukkan apa yang dilihatnya, dengan tangkapan skrin. Layari yang lulus dan terima dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap penyerahan menunjukkan apa yang berubah: fail, perbezaan, tangkapan skrin. Tak perlu buka setiap aplikasi untuk tahu sama ada ia siap.","f.chat.h":"Berbual dengan ketua anda","f.chat.p":"Bar gaya Discord: satu ikon bagi setiap projek, berlian ungu untuk apa yang perlukan anda. Hantar idea kepada ketua; dia mengubahnya menjadi kad dan pelan, dengan butang ✅ Mula.","f.tidy.h":"Mengemas sendiri","f.tidy.p":"Kad yang berkaitan digabungkan menjadi satu, tajuk yang kusut dibetulkan, dan semakan token memastikan kod kekal ringkas. Kurang perkara untuk ditukar-tukar, kurang untuk difikirkan.","f.private.h":"Milik anda, pada komputer anda","f.private.li1":"Papan ini berjalan pada komputer anda sendiri dan hanya menjawab anda.","f.private.li2":"Mesej peribadi antara orang disulitkan hujung ke hujung.","f.private.li3":"Tiada akaun, tiada penjejak, tiada kuki.","f.lang.h":"Dalam bahasa anda","f.lang.p":"Lebih 120 bahasa, daripada Belanda, Wales dan Jepun hingga lanun, Yoda dan Klingon, dengan pertukaran pantas kembali ke bahasa Inggeris untuk jargon industri.","f.service.h":"Daripada idea kepada perkhidmatan sebenar","f.service.p":"Membina sesuatu dengan AI yang kini digunakan orang? Tandakan ia sebagai perkhidmatan dan papan membantu anda menjalankannya dengan baik: semakan uptime, halaman status awam, insiden dengan laporan, perubahan yang memerlukan Go, sandaran yang disemak setiap hari. Bantuan mengajar setiap langkah sambil anda berjalan.","msgr.h2":"AI-gile Messenger: pasukan anda dalam poket","msgr.p1":"Bercakap dengan pasukan AI anda tanpa membuka papan. Bersembang dengan ketua projek dan rakan-rakan anda, lihat langkah ujian kad dan jawabnya, semuanya dari telefon anda.","msgr.p2":"Untuk memasangkannya, imbas kod QR pada papan anda. Kali pertama? Sembang demo yang mesra akan membawa anda melihat-lihat.","msgr.when":"Android dahulu, kemudian versi web untuk telefon dan iPhone.","msgr.who":"Ketua projek anda","msgr.b1":"Pembaikan mod gelap sudah siap. Mahu langkah ujiannya?","msgr.b2":"Ya, boleh!","msgr.b3":"1. Buka Tetapan. 2. Pilih Gelap. Nampak betul?","tl.aria":"Garis masa dari perbualan pertama hingga pelan hala tuju","tl.h2":"Dari sembang pertama hingga apa yang seterusnya","tl.lede":"Tarikh dan masa sebenar, dalam zon waktu anda sendiri. Selepas hari ini ia ialah pelan, tanpa tarikh yang dijanjikan.","tl.today":"Hari ini","tl.planned":"dirancang","tl.doing":"sedang dibuat","tl.cards.one":"{n} kad","tl.cards.other":"{n} kad","join.h2":"Sertai kami","join.lede":"AI-gile dibina oleh seorang lelaki pelik berjanggut yang ada AuDHD dan beberapa perjuangan kesihatan mental, serta ramai ejen yang sabar. Buat masa ini ia persendirian, dalam alfa tertutup bersama kawan-kawan. Mahu mencuba bila ia dibuka?","join.btn":"Daftar minat","join.small":"Kami akan e-mel anda, tidak lebih","footer.tag":"AI-gile. Tiada penjejak, tiada kuki, tiada kopi stand-up.","footer.licence":"Lesen perniagaan","footer.status":"Status","footer.privacy":"Apa yang kami simpan","footer.thanks":"Panggilan dengan ihsan ChilledChat","form.sending":"Menghantar…","form.failed":"Tidak berjaya: cuba lagi nanti.","form.offline":"Tidak dapat menghubungi AI-gile: cuba lagi nanti.","form.keep":"Kami hanya menggunakan ini untuk membalas anda, kemudian memadamnya. Tiada penjejak, tiada kuki.","form.keepLink":"Apa yang kami simpan","interest.title":"AI-gile: beritahu saya bila alfa dibuka","interest.description":"Tinggalkan e-mel anda untuk tahu bila alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Beritahu saya bila ia dibuka","interest.lede":"AI-gile berada dalam pra-alfa tertutup. Tinggalkan e-mel anda dan kami akan menulis sekali sahaja, apabila ada tempat untuk anda.","interest.email":"E-mel anda","interest.which":"Ujian yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, lebih lewat","interest.both":"Mana-mana, yang datang dahulu","interest.submit":"Masukkan saya dalam senarai","interest.thanks":"Terima kasih! Anda sudah ada dalam senarai.","licence.title":"AI-gile: lesen perniagaan","licence.description":"Guna AI-gile dalam perniagaan anda? Mohon lesen perniagaan percuma.","licence.h1":"📜 Lesen perniagaan","licence.lede":"Guna AI-gile di tempat kerja? Beritahu kami siapa anda dan apa yang anda buat. Jika ia membawa kebaikan, lesen ini percuma.","licence.company":"Syarikat","licence.website":"Laman web","licence.what":"Apa yang anda buat","licence.how":"Bagaimana ia membantu dunia","licence.email":"E-mel","licence.submit":"Mohon","licence.thanks":"Terima kasih! Kami akan membalas melalui e-mel.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semuanya tenang","status.intro":"Adakah AI-gile berfungsi sekarang? Halaman ini menyemak laman web, perkongsian papan, panggilan dan muat turun setiap 5 minit.","status.up":"Berfungsi (menjawab dalam {ms} ms)","status.slow":"Tidak menjawab semakan terakhir, mencuba lagi","status.down":"Terhenti: tidak menjawab dua semakan terakhir","status.svc.web":"Laman web","status.svc.web.offers":"Laman ini: apa itu AI-gile, dan borang minat","status.svc.boards":"Perkongsian papan","status.svc.boards.offers":"Papan awam, mesej antara rakan dan jemputan","status.svc.calls":"Panggilan","status.svc.calls.offers":"Suara, video dan perkongsian skrin dalam AI-gile","status.svc.download":"Muat turun","status.svc.download.offers":"Pemasang Windows dan pautan jemputan","status.checking":"Menyemak…","status.offline":"Tidak dapat menghubungi perkhidmatan status sekarang (mencuba semula)","status.updated":"dikemas kini {ago}","status.justNow":"baru sahaja","status.min":"{n} min lalu","status.hours":"{n} j lalu","status.days":"{n} h lalu","privacy.title":"AI-gile: apa yang kami simpan","privacy.h1":"Apa yang kami simpan","privacy.lede":"Ringkasnya: hanya apa yang anda hantar kepada kami, dan tidak lama.","privacy.only":"Hanya apa yang anda hantar kepada kami: apa yang anda taip dalam borang, seperti e-mel anda. Tiada apa-apa lagi tentang anda.","privacy.sealed":"Ia dimeterai supaya pelayan kami tidak dapat membacanya: dalam pelayar anda sebelum ia dihantar (pada pelayar yang lebih lama, sebaik sahaja ia tiba). Hanya papan kami sendiri yang boleh membukanya.","privacy.server":"Ia dipadam daripada pelayan sebaik sahaja ia sampai ke papan kami. Apa-apa yang masih ada di situ selepas 30 hari akan dipadam juga.","privacy.board":"Kami menyimpannya pada papan kami hanya sehingga kami membalas anda, kemudian memadamnya di situ juga.","privacy.none":"Tiada penjejak, tiada kuki, tiada analitik.","privacy.local":"Bahasa anda dan pilihan tema cerah atau gelap kekal dalam pelayar anda sendiri. Ia tidak pernah dihantar kepada kami.","privacy.ask":"Mahu ia dipadam lebih awal? Balas e-mel kami dan beritahu kami.","live.h2":"Tonton ia dibina, secara langsung","live.caption":"Setiap kad disembunyikan: anda lihat bentuk kerja, bukan perkataannya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.last.now":"Kad terakhir dialihkan sebentar tadi","live.last.min.one":"Kad terakhir dialihkan {n} minit lalu","live.last.min.other":"Kad terakhir dialihkan {n} minit lalu","live.last.hour.one":"Kad terakhir dialihkan {n} jam lalu","live.last.hour.other":"Kad terakhir dialihkan {n} jam lalu","live.last.day.one":"Kad terakhir dialihkan {n} hari lalu","live.last.day.other":"Kad terakhir dialihkan {n} hari lalu","live.offline":"Papan langsung sedang berehat sebentar. Datang lagi nanti.","live.cols":"Backlog|Untuk dibuat|Sedang dibuat|Pasukan menyemak|Untuk anda uji|Untuk pasukan|Selesai"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Diwakilkan."]},{"n":2,"texts":["Kanban robot.","Ejen, tersusun.","Idea, terbina."]},{"n":3,"texts":["Kanban untuk robot.","Idea jadi fungsi.","Kanban ejen percuma."]},{"n":5,"texts":["Papan kanban dijalankan oleh ejen.","Anda tulis kad. Ejen membina.","Percuma, setempat, teruji, agak lucu."]},{"n":8,"texts":["Papan kanban percuma tempat ejen AI bekerja.","Tulis idea. Ejen membinanya. Anda menerima.","Agile untuk seorang manusia dan ramai robot sabar."]},{"n":13,"texts":["Papan kanban pada komputer anda di mana ejen AI mengambil kad satu demi satu.","Tulis satu idea. Pasukan ejen membinanya. Seorang penguji menyemaknya dan menunjukkan hasilnya.","Tiada akaun, tiada penjejak: sebuah papan, beberapa robot, dan anda yang menentukan segalanya."]},{"n":21,"texts":["AI-gile ialah papan kanban untuk bekerja dengan ejen pengekodan AI. Mereka mengambil kad satu demi satu; anda menguji dan menerimanya.","Setiap projek ada seorang ketua dan pasukan ejen AI. Beri komen pada mana-mana kad dan pasukan itu terus mula bekerja.","Papan tugasan peribadi yang percuma dan berjalan pada komputer anda sendiri. Pekerjanya robot. Yang berkata ya ialah anda."]},{"n":34,"texts":["Anda letak idea pada papan. Pasukan ejen AI mengubahnya menjadi ciri yang berfungsi, mengujinya, dan menyerahkannya semula dengan langkah untuk dicuba. Tiada apa dikira siap sehingga anda berkata begitu.","AI-gile ialah papan kanban buatan sendiri yang dibina oleh Rich dengan banyak bantuan daripada ejen yang kini diuruskannya. Ia percuma, berjalan pada komputer anda, dan dikongsi dengan kawan, bukan dijual.","Bayangkan papan kanban biasa dengan lajur dari Backlog hingga Selesai, cuma kadnya diambil oleh ejen AI. Mereka melapor kemajuan, bertanya apabila tersangkut, dan sentiasa menunggu persetujuan anda dahulu."]},{"n":55,"texts":["AI-gile ialah papan kanban yang pasukannya terdiri daripada ejen AI. Setiap projek ada seorang ketua yang merancang kerja dan pembantu yang membinanya. Apabila sesuatu ciri siap, seorang penguji AI mencubanya dan mengambil tangkapan skrin, kemudian ia sampai ke longgokan anda. Terima, atau beri komen dan mereka mengerjakannya semula.","Ia bermula sebagai cara seorang untuk menjejak banyak sesi pengekodan AI serentak, lalu membesar menjadi papan sebenar. Ia berjalan pada mesin anda, tidak perlukan akaun, dan tiada penjejak. Ia percuma untuk kawan dan sesiapa yang ingin tahu. Ia juga belum siap, jadi jangan terkejut dengan tepi yang kasar dan kejutan sekali-sekala.","Inilah versi jujurnya. Anda masih perlu memikirkan idea, dan anda masih perlu menyemak hasilnya. AI-gile melakukan semua yang di antaranya: ia menyusun kad, membangunkan ejen yang betul apabila anda memberi komen, menunjukkan apa yang tepat berubah, dan mengumpulkan semuanya dalam satu longgokan pendek untuk anda, supaya anda tak perlu berlari antara aplikasi."]},{"n":89,"texts":["AI-gile ialah papan kanban percuma yang anda jalankan pada komputer anda sendiri. Bukannya orang, setiap projek ada pasukan ejen AI: seorang ketua yang mengubah idea anda menjadi kad dan pelan, dan pembantu yang mengambil kad mengikut keutamaan. Apabila sesuatu siap dibina, penguji AI mengikut langkah ujian dan menunjukkan apa yang dilihatnya. Kemudian ia menunggu dalam satu longgokan bernama Untuk anda. Anda menerimanya, atau beri komen dan pasukan itu mencuba lagi. Tiada apa sampai ke Selesai tanpa anda.","Beberapa perkara yang mungkin tidak anda sangka. Rondaan malam memastikan lajur Untuk dibuat sentiasa terisi semasa anda tidur, memilih kad yang tidak memerlukan jawapan daripada anda. Pembilang token menunjukkan berapa banyak yang ejen gunakan hari ini dan minggu ini, dan Mod Tanpa Token menyuruh mereka berhenti menggunakan token. Anda boleh menghantar mesej kepada kawan, dan mesej peribadi disulitkan hujung ke hujung. Papan ini bertutur dalam kira-kira 120 bahasa, termasuk Belanda, Flemish, lanun dan Klingon. Semua ini percuma, dan tiada sesiapa cuba menjualnya kepada anda.","AI-gile ialah projek peribadi yang kecil, bukan syarikat. Rich mahu menjaga beberapa projek pengekodan AI tanpa membuka setiap aplikasi untuk menyemaknya, maka dia dan ejen membina sebuah papan untuknya, kemudian menggunakan papan itu untuk membina selebihnya sendiri. Ia dalam pra-alfa tertutup, bermakna ia berfungsi, kebanyakannya, untuk segelintir kawan. Tiada halaman harga, tiada surat berita dan tiada pelan pertumbuhan. Tiada sesiapa mengumpul data anda. Jika kedengaran berguna, anda boleh minta untuk mencubanya apabila ia dibuka sedikit lagi."]},{"n":144,"texts":["AI-gile ialah papan kanban untuk seorang manusia dan ramai ejen AI. Ia berjalan pada komputer anda sendiri dan sepenuhnya percuma. Anda menambah projek, dan setiap projek mendapat seorang ketua dan pasukan kecil. Anda berbual dengan ketua, sedikit seperti Discord, dan menerangkan idea; ketua mengubahnya menjadi kad dan pelan, kemudian menunggu anda menekan Mula. Pasukan mengerjakan kad mengikut keutamaan, menggunakan barisan arahan ringkas yang dibuat untuk model bahasa. Sebelum apa-apa kembali kepada anda, penguji AI mengikut langkah dalam salinan aplikasi dan melampirkan tangkapan skrin. Kerja yang siap sampai ke longgokan anda bersama fail yang berubah dan perbezaannya. Anda menerimanya, atau meninggalkan komen dan pasukan itu bangun dan mencuba lagi. Papan ini juga mengemas sendiri: kad yang berkaitan digabungkan. Hanya anda yang boleh menggerakkan kad ke Selesai.","Begini lebih kurang sehari dengan AI-gile. Waktu petang anda tinggalkan beberapa komen: butang ini salah tempat, senarai itu patut diisih, boleh tak ada mod gelap. Anda pergi tidur. Ejen membaca komen, membuat perubahan, mengujinya dan menyerahkannya semula kepada anda. Jika Untuk dibuat kehabisan, rondaan malam mengisinya daripada backlog dengan kad yang tidak memerlukan jawapan anda. Pada waktu pagi ada satu longgokan pendek: beberapa soalan dan beberapa perkara untuk dicuba, setiap satu dengan langkah yang boleh diikuti oleh orang mengantuk dan tangkapan skrin ia berfungsi. Anda klik, terima yang baik dan hantar balik selebihnya. Jika ada yang kurang jelas, anda cuma beri komen dan ia kembali kepada pasukan. Pembilang token menunjukkan berapa banyak digunakan, dan Mod Tanpa Token ada untuk minggu yang jimat. Kemudian anda bersarapan, yang ejen belum boleh bantu.","Pertama, apa yang AI-gile bukan. Ia bukan syarikat permulaan, ia tidak dijual, dan tiada sesiapa mengumpul data anda. Ia papan percuma yang berjalan pada komputer anda, tanpa akaun, tanpa penjejak dan tanpa kuki. Apa dia: satu tempat kemas untuk melihat setiap projek pengekodan AI sekali gus, dengan pasukan ejen membuat kad dan anda membuat keputusan. Ada juga rondaan malam yang menyediakan kad semasa anda tidur. Ia menggabungkan kad yang berkaitan, membetulkan tajuk yang kusut, dan memerhati supaya kod kekal ringkas. Ia bertutur dalam kira-kira 120 bahasa, dari Belanda dan Flemish hingga lanun dan Klingon. Kawan boleh bermesej sesama sendiri, secara peribadi dan disulitkan. Ia dibina oleh Rich dan ramai ejen yang sabar, kebanyakannya menggunakan papan itu sendiri. Ia dalam pra-alfa tertutup, jadi ada bahagian yang kasar. Jika kedengaran menyeronokkan, minta dengan baik dan mungkin anda masuk awal."]}],"quips":{"1":"Satu perkataan. Berani. Mungkin terlalu berani.","3":"Tiga perkataan. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Lapan perkataan. Masih lebih pendek daripada satu stand-up.","21":"Panjang ini ialah story point, by the way. Sudah tentu.","55":"Lima puluh lima perkataan. Dua kad siap semasa anda membaca itu.","144":"Itulah yang panjang. Tiada 233. Ejen sudah pergi tidur."}},"timeline":{"first-idea.name":"Idea pertama","first-idea.line":"Perbualan paling awal, sebelum wujud sebarang kod.","first-board.name":"Papan pertama","first-board.line":"Papan yang menjejak pembinaannya sendiri: kad, lajur, seret dan lepas, projek.","team-roles.name":"Pasukan dan peranan","team-roles.line":"Profil ejen, templat pasukan, ruang dan siapa buat apa.","install.name":"Pemasangan dan keluaran","install.line":"Fail zip yang boleh dipasang oleh kawan, kemas kini sendiri, saluran dan undur semula.","usage-saver.name":"Penjimat penggunaan","usage-saver.line":"Ukur kos setiap larian, kekalkan kod ringkas, jimatkan had anda.","friends.name":"Kawan dan perkongsian","friends.line":"Mesej peribadi, geganti terenkripsi, jemputan, peranan dan projek kongsi.","languages.name":"Bahasa","languages.line":"Setiap teks skrin dalam fail bahasa, bermula dengan Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Seorang penguji menyemak setiap penyerahan dahulu dan menunjukkan apa yang dilihatnya.","website.name":"Laman web","website.line":"aigile.lol, teaser dan garis masa ini.","streaming.name":"Sembang dan penstriman","streaming.line":"Discord, Twitch, OBS, mod penstrim, GIF dan emoji.","no-ai.name":"Edisi tanpa AI","no-ai.line":"Papan untuk orang yang mengekod tanpa AI, dan papan awam.","night-watch.name":"Rondaan malam","night-watch.line":"Seorang pengawal dan Scrum Master memastikan pasukan kekal pada tugas semasa anda tidur.","p-more.name":"Selebihnya","p-more.line":"Idea yang lebih kecil, masih menunggu giliran.","p-android.name":"Telefon dan Android","p-android.line":"Capai papan anda dari telefon, kemudian aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, laman langsung, kemudian beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"130 bahasa, dan mod rendaman untuk pelajar.","p-engines.name":"Lebih banyak enjin AI","p-engines.line":"Pilih Claude, Codex, Gemini, Copilot atau Cursor untuk setiap ejen.","p-pro.name":"Amalan profesional","p-pro.line":"Label risiko, pintu gabungan, kad insiden dan pagar pelindung.","p-self.name":"Menjaga anda","p-self.line":"Mod penat, peringatan jaga diri dan 4:20.","p-servers.name":"Pelayan dan skala","p-servers.line":"Tetapan pelayan global, peranan dan perancangan untuk pertumbuhan.","p-livestream.name":"Tambahan penstriman","p-livestream.line":"Sembang Twitch, emoji tersuai dan paparan langsung awam."},"words":{"button":"📖 Jargon industri","h":"📖 Perkataan diterangkan","intro":"Latihan percuma dalam bahasa mudah: setiap perkataan yang anda temui dari idea pertama hingga perkhidmatan yang dipercayai orang, dengan Agile, pembinaan, memastikannya selamat dan bekerja dengan AI sepanjang perjalanan.","search":"Cari perkataan…","none":"Tiada perkataan yang sepadan.","close":"Tutup","count":{"one":"{count} perkataan","other":"{count} perkataan"},"groups":[{"id":"idea","name":"💡 Idea dan penerokaan"},{"id":"plan","name":"🗺️ Merancang kerja"},{"id":"agile","name":"🔁 Cara kerja Agile"},{"id":"build","name":"🛠️ Membina"},{"id":"test","name":"🧪 Ujian dan kualiti"},{"id":"change","name":"🔀 Mengubah dengan selamat"},{"id":"run","name":"🛎️ Menjalankan perkhidmatan"},{"id":"sec","name":"🔒 Keselamatan dan privasi"},{"id":"ai","name":"🤖 Bekerja dengan AI"},{"id":"money","name":"💰 Wang dan lesen"}],"list":[{"id":"discovery","g":"idea","word":"Penerokaan","text":"Peringkat awal untuk mengetahui masalah mana yang berbaloi diselesaikan dan untuk siapa, sebelum apa-apa dibina.","also":["fasa penerokaan","discovery"]},{"id":"problemstmt","g":"idea","word":"Pernyataan masalah","text":"Satu atau dua ayat yang menyatakan siapa yang mempunyai masalah, apa masalahnya dan mengapa ia penting, supaya semua orang menuju ke arah yang sama.","also":["pernyataan masalah"]},{"id":"user","g":"idea","word":"Pengguna","text":"Orang yang menggunakan apa yang anda bina. Keperluan mereka ialah tujuan kerja itu.","also":["pengguna","user"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Pihak berkepentingan","text":"Sesiapa yang mengambil berat tentang hasil kerja atau terkesan olehnya, seperti orang yang membiayainya, menggunakannya atau menyokongnya.","also":["pihak berkepentingan","stakeholder"]},{"id":"persona","g":"idea","word":"Persona","text":"Orang rekaan tetapi realistik yang mewakili satu jenis pengguna, supaya pasukan boleh bertanya “adakah Sam akan rasa ini mudah?”","also":["persona","watak pengguna"]},{"id":"userresearch","g":"idea","word":"Kajian pengguna","text":"Bercakap dengan dan memerhati orang sebenar untuk mengetahui apa yang mereka perlukan, bukannya meneka.","also":["temu bual pengguna","user research"]},{"id":"journey","g":"idea","word":"Perjalanan pengguna","text":"Langkah yang diambil seseorang untuk menyiapkan sesuatu, dari mula mendengar tentangnya hingga selesai, termasuk di luar produk anda. Melukisnya menunjukkan di mana mereka tersangkut.","also":["perjalanan pengguna","perjalanan pelanggan","user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Titik masalah","text":"Sesuatu yang menjengkelkan atau melambatkan orang pada hari ini. Produk yang baik menghapuskan titik masalah.","also":["titik masalah","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Andaian","text":"Sesuatu yang anda percaya tetapi belum disemak. Menulis andaian menunjukkan apa yang patut diuji dahulu.","also":["andaian","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotesis","text":"Tekaan terbaik yang anda rancang untuk disemak, dengan apa yang anda jangka berlaku, seperti “orang akan mendaftar jika bulan pertama percuma”.","also":["hipotesis","hypothesis"]},{"id":"experiment","g":"idea","word":"Eksperimen","text":"Ujian kecil yang dirancang untuk mengetahui sama ada sesuatu idea berjaya, sebelum anda bertaruh banyak padanya.","also":["eksperimen","ujikaji"],"noTip":1},{"id":"poc","g":"idea","word":"Bukti konsep (PoC)","text":"Percubaan pantas dan kasar untuk melihat sama ada sesuatu idea boleh berjaya langsung. Biasanya dibuang sebaik sahaja anda mendapat jawapan.","also":["PoC","proof of concept","bukti konsep"]},{"id":"prototype","g":"idea","word":"Prototaip","text":"Model awal produk, selalunya gambar yang boleh diklik, untuk mencuba idea pada orang sebelum membinanya dengan betul.","also":["prototaip","prototype"]},{"id":"wireframe","g":"idea","word":"Rangka dawai","text":"Lakaran ringkas sesebuah skrin yang menunjukkan di mana letak setiap benda, tanpa warna atau kandungan sebenar.","also":["rangka dawai","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Gambar terperinci bagaimana sesebuah skrin akan kelihatan, dengan warna dan teks sebenar, tetapi belum ada apa-apa yang berfungsi.","also":["mockup","mock-up","model rupa"]},{"id":"bizcase","g":"idea","word":"Kes perniagaan","text":"Sebab-sebab untuk melakukan sesuatu projek: kosnya, apa yang dibawa masuk atau dijimatkan, dan risikonya.","also":["kes perniagaan","business case"]},{"id":"feasibility","g":"idea","word":"Kebolehlaksanaan","text":"Sama ada sesuatu benar-benar boleh dibina dan dijaga dengan masa, wang dan kemahiran yang anda ada.","also":["boleh dilaksanakan","feasibility"]},{"id":"outcome","g":"idea","word":"Hasil akhir","text":"Perubahan yang anda mahu untuk orang, seperti kurang temu janji terlepas. Ia lebih penting daripada banyak mana yang anda bina.","also":["hasil akhir","outcome"],"noTip":1},{"id":"output","g":"idea","word":"Keluaran","text":"Sesuatu yang dihasilkan pasukan, seperti skrin baharu atau laporan. Menghasilkannya tidak semestinya membantu sesiapa.","also":["keluaran","output"],"noTip":1},{"id":"successmetric","g":"idea","word":"Metrik kejayaan","text":"Nombor yang memberitahu anda sama ada kerja itu mencapai tujuannya, seperti lebih ramai orang menyiapkan pesanan mereka.","also":["metrik kejayaan","success metric"]},{"id":"kpi","g":"idea","word":"Petunjuk prestasi utama (KPI)","text":"Nombor penting yang anda pantau untuk melihat sama ada keadaan berjalan baik, seperti jumlah pendaftaran setiap minggu.","also":["KPI","KPIs","petunjuk prestasi utama","key performance indicator"]},{"id":"okr","g":"idea","word":"Objektif dan hasil utama (OKR)","text":"Cara menetapkan matlamat: objektif menyatakan apa yang anda mahu, dan beberapa hasil utama ialah nombor yang menunjukkan anda sudah sampai.","also":["OKR","OKRs","objectives and key results"]},{"id":"product","g":"plan","word":"Produk","text":"Benda yang dibina dan dijaga untuk penggunanya, seperti aplikasi, laman web atau alat.","also":["produk","product"],"noTip":1},{"id":"vision","g":"plan","word":"Visi produk","text":"Pernyataan ringkas tentang siapa yang dibantu produk itu dan ke mana arahnya dalam jangka panjang.","also":["visi produk","pernyataan visi","vision statement"]},{"id":"po","g":"plan","word":"Pemilik produk (PO)","text":"Orang yang menentukan apa yang dibina dan dalam susunan mana, supaya pasukan sentiasa mengusahakan yang paling penting. Dalam AI-gile itu ialah anda.","also":["PO","pemilik produk","product owner"]},{"id":"pm","g":"plan","word":"Pengurus produk (PM)","text":"Orang yang menjaga hala tuju sesebuah produk: masalah mana yang diselesaikan, untuk siapa dan mengapa. PM juga boleh bermaksud pengurus projek, jadi semak yang mana satu.","also":["PM","pengurus produk","product manager"]},{"id":"projmgr","g":"plan","word":"Pengurus projek","text":"Orang yang memastikan projek mengikut masa dan bajet, menjejak siapa melakukan apa dan bila.","also":["pengurus projek","project manager"]},{"id":"roadmap","g":"plan","word":"Peta hala tuju","text":"Pelan kasar tentang apa yang akan datang dalam beberapa bulan seterusnya, mengikut susunan. Ia menunjukkan arah, bukan tarikh tepat, dan berubah apabila anda belajar.","also":["peta hala tuju","roadmap"]},{"id":"milestone","g":"plan","word":"Pencapaian","text":"Satu titik dalam projek yang wajar ditandakan, seperti “versi pertama dilancarkan” atau “100 pengguna”.","also":["pencapaian","milestone","tonggak"]},{"id":"mvp","g":"plan","word":"Produk berdaya maju minimum (MVP)","text":"Versi produk yang paling kecil yang masih berguna kepada orang sebenar, supaya anda boleh belajar daripada mereka lebih awal.","also":["MVP","MVPs","produk berdaya maju minimum","minimum viable product"]},{"id":"requirement","g":"plan","word":"Keperluan","text":"Sesuatu yang mesti dilakukan atau dimiliki oleh produk yang siap.","also":["keperluan","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Skop","text":"Apa yang termasuk dalam kerja itu dan, sama penting, apa yang tidak.","also":["dalam skop","luar skop","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Skop menjalar","text":"Apabila semakin lama semakin banyak ditambah pada kerja sedikit demi sedikit, tanpa sesiapa bersetuju tentang masa atau kos tambahan, sehingga ia tidak pernah siap.","also":["feature creep","scope creep","skop merebak"]},{"id":"feature","g":"plan","word":"Ciri","text":"Satu perkara yang boleh dilakukan produk untuk orang, seperti “tetapkan semula kata laluan anda”.","also":["ciri","feature"],"noTip":1},{"id":"epic","g":"plan","word":"Epik","text":"Kerja besar, terlalu besar untuk sekali buat, jadi ia dipecahkan kepada kad yang lebih kecil.","also":["epik","epic"]},{"id":"story","g":"plan","word":"Cerita pengguna","text":"Kerja kecil yang ditulis dari sudut pandangan pengguna: “Sebagai pembeli, saya mahu menyimpan bakul saya, supaya saya boleh menyiapkannya kemudian.” Ia memulakan perbualan tentang apa yang perlu dibina.","also":["cerita pengguna","user story","user stories"]},{"id":"ac","g":"plan","word":"Kriteria penerimaan (AC)","text":"Semakan yang mesti dilepasi sesebuah kad untuk dikira siap, dipersetujui sebelum kerja bermula, seperti “bakul masih ada selepas saya log keluar dan masuk semula”.","also":["AC","kriteria penerimaan","acceptance criteria"]},{"id":"task","g":"plan","word":"Tugasan","text":"Satu kerja tunggal yang perlu dibuat, selalunya satu langkah kecil daripada sebuah cerita yang lebih besar.","also":["tugasan","task"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket","text":"Perkataan lain untuk kad: satu kerja atau satu permintaan, dijejak dari mula hingga akhir.","also":["tiket","ticket"]},{"id":"priority","g":"plan","word":"Keutamaan","text":"Betapa penting atau mendesaknya sesuatu berbanding yang lain, supaya kerja paling penting didahulukan.","also":["keutamaan","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Pengutamaan","text":"Menyusun kerja mengikut tahap kepentingan. Cara biasa ialah MoSCoW: Must have (mesti ada), Should have (patut ada), Could have (boleh ada), Won’t have (tidak buat kali ini).","also":["mengutamakan","MoSCoW"]},{"id":"estimate","g":"plan","word":"Anggaran","text":"Tekaan terbaik tentang betapa besar atau betapa lama sesuatu kerja. Ia tekaan, bukan janji.","also":["anggaran","estimate","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Mata cerita","text":"Cara meneka saiz kerja dengan membandingkan kad antara satu sama lain (“lebih kurang dua kali ganda daripada yang itu”) dan bukannya dalam jam. Ia bukan untuk membandingkan pasukan.","also":["mata cerita","story point","story points"]},{"id":"tshirt","g":"plan","word":"Saiz baju-T","text":"Meneka saiz kerja sebagai S, M, L atau XL. Cepat dan memadai untuk perancangan awal.","also":["saiz baju-T","T-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Poker perancangan","text":"Permainan untuk menganggar: semua orang menunjukkan kad saiz serentak, kemudian yang tertinggi dan terendah menerangkan sebabnya.","also":["Scrum poker","planning poker"]},{"id":"dependency","g":"plan","word":"Kebergantungan","text":"Apabila satu kerja tidak boleh bermula atau siap selagi kerja lain belum bermula atau siap.","also":["kebergantungan","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Penghalang","text":"Apa-apa yang menghalang kerja daripada bergerak ke hadapan sekarang, seperti jawapan yang belum ada atau alat yang rosak.","also":["penghalang","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Tarikh akhir","text":"Tarikh sesuatu mesti disiapkan.","also":["tarikh akhir","tarikh tutup","deadline"],"noTip":1},{"id":"deliverable","g":"plan","word":"Hasil serahan","text":"Sesuatu yang nyata yang dihasilkan dan diserahkan oleh kerja itu, seperti halaman yang berfungsi atau laporan.","also":["hasil serahan","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Ramalan","text":"Jangkaan tentang apa yang mungkin berlaku, seperti bila kerja akan siap, berdasarkan apa yang anda tahu setakat ini.","also":["ramalan","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metrik","text":"Apa-apa yang anda ukur dan jejak dari semasa ke semasa, seperti lawatan halaman atau berapa lama masa yang diambil untuk sesuatu pembaikan.","also":["metrik","metric","metrics"]},{"id":"feedback","g":"plan","word":"Maklum balas","text":"Apa yang orang katakan tentang kerja anda, baik dan buruk. Mendapatnya awal dan kerap ialah inti Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Senarai menunggu bagi idea dan kerja yang belum dirancang, dengan yang paling penting di atas. Tiada apa-apa di situ dikerjakan sehingga ia berpindah ke Untuk dibuat."},{"id":"sprint","g":"agile","word":"Sprint","text":"Tempoh kerja yang pendek dan tetap (selalunya satu atau dua minggu, tidak pernah lebih daripada sebulan) dengan matlamat dan set kad yang dipersetujui untuk disiapkan.","also":["sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Semakan pantas setiap hari: apa yang dibuat setiap ahli pasukan, apa yang mereka buat seterusnya, dan apa yang menghalang mereka. Dalam Scrum ia dipanggil scrum harian.","also":["standup","stand-up","scrum harian","daily scrum","daily stand-up","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Cara bekerja di mana kad bergerak merentasi lajur papan (seperti Untuk dibuat, Sedang dibuat, Selesai) dan pasukan mengehadkan berapa banyak yang sedang dikerjakan serentak, supaya kerja terus mengalir."},{"id":"wip","g":"agile","word":"Had WIP","text":"WIP singkatan bagi work in progress (kerja sedang dijalankan). Had WIP ialah bilangan kad paling banyak yang patut ada dalam satu lajur serentak, supaya pasukan menyiapkan sesuatu sebelum memulakan yang lain.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Senarai semak ringkas pasukan tentang maksud “siap”, seperti sudah diuji dan diterangkan, sebelum kad diserahkan kepada anda. Kembarnya, Definition of Ready, menyatakan bila kad cukup jelas untuk dimulakan.","also":["Definition of Ready","DoD","DoR","takrif selesai","takrif sedia"]},{"id":"retro","g":"agile","word":"Retro","text":"Imbasan semula secara berkala tentang cara pasukan bekerja, untuk bersetuju melakukan satu atau dua perkara dengan lebih baik pada kali seterusnya. Singkatan bagi retrospektif. Dalam AI-gile, retro mencadangkan perubahan pada cara kerja pasukan, dan anda mengatakan Go atau Belum lagi.","also":["retrospektif"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Semua orang turun padang: ramai orang meninggalkan kerja lain untuk membetulkan satu perkara mendesak bersama-sama sehingga selesai. Dalam AI-gile setiap pasukan membantu satu projek, dan projek lain menunggu sementara itu.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Dalam Scrum, orang yang membantu pasukan bekerja dengan baik: menyingkirkan halangan mereka, memastikan mesyuarat teratur dan melatih tabiat baik, tanpa memerintah sesiapa. Dalam AI-gile, Lead Scrum Master mengesan kad yang tersekat, mendorong pasukan dan mengingatkan anda tentang apa yang menunggu, merentasi setiap projek.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Cara bekerja dalam langkah kecil: bina sedikit, tunjukkan hasil sebenar dengan kerap, belajar daripada kata orang dan ubah rancangan sambil jalan, bukannya merancang segala-galanya di awal.","also":["pembangunan Agile","cara kerja Agile"]},{"id":"manifesto","g":"agile","word":"Manifesto Agile","text":"Pernyataan ringkas yang ditulis pada 2001 oleh pembuat perisian. Ia mengutamakan orang, hasil yang berfungsi, kerjasama rapat dengan pelanggan dan tindak balas kepada perubahan berbanding rancangan dan dokumentasi yang berat.","also":["Manifesto for Agile Software Development","Agile Manifesto"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Cara kerja lama: rancang segala-galanya, kemudian bina semuanya, kemudian uji semuanya, satu demi satu peringkat. Perubahan pada peringkat lewat sukar dan mahal.","also":["model waterfall","model air terjun"]},{"id":"iteration","g":"agile","word":"Lelaran","text":"Satu pusingan membina sesuatu, menyemaknya dan memperbaikinya. Kerja Agile ialah rangkaian pusingan ini, dan sprint ialah satu jenisnya.","also":["lelaran","iterasi","iteration"]},{"id":"increment","g":"agile","word":"Tokokan","text":"Bahagian baharu yang berfungsi, ditambah pada produk dalam satu sprint atau pusingan kerja, yang sesuai dengan apa yang sudah ada.","also":["tokokan","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Cara kerja Agile yang popular: pasukan kecil bekerja dalam sprint pendek menuju satu matlamat, dengan peranan tetap dan beberapa mesyuarat berkala untuk merancang, menyemak dan memperbaiki."},{"id":"scrumteam","g":"agile","word":"Pasukan Scrum","text":"Kumpulan kecil yang melakukan kerja dalam Scrum: seorang pemilik produk, seorang Scrum Master dan pembangunnya.","also":["pasukan Scrum","Scrum team"]},{"id":"ceremonies","g":"agile","word":"Acara Scrum","text":"Mesyuarat berkala dalam Scrum: perancangan sprint, scrum harian, semakan sprint dan retro. Ramai menyebutnya upacara (ceremonies).","also":["upacara","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Perancangan sprint","text":"Mesyuarat pada permulaan sprint di mana pasukan bersetuju mengapa sprint itu penting, kad mana yang akan diambil dan bagaimana hendak bermula.","also":["mesyuarat perancangan","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Matlamat sprint","text":"Satu ayat yang menyatakan untuk apa sesuatu sprint. Tugasan kecil boleh berubah sepanjang jalan, asalkan matlamat tercapai.","also":["matlamat sprint","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Backlog sprint","text":"Kad yang dipilih untuk sprint semasa, bersama rancangan pasukan untuk melakukannya.","also":["backlog sprint","sprint backlog"]},{"id":"productbacklog","g":"agile","word":"Backlog produk","text":"Senarai lengkap yang tersusun bagi segala yang mungkin dibina untuk produk, yang terpenting di atas. Ia terus berubah apabila anda belajar.","also":["backlog produk","product backlog"]},{"id":"productgoal","g":"agile","word":"Matlamat produk","text":"Hasil yang lebih besar yang dituju oleh produk, yang membantu pasukan memilih apa yang perlu dibuat seterusnya.","also":["matlamat produk","product goal"]},{"id":"refinement","g":"agile","word":"Penghalusan backlog","text":"Menyemak backlog dengan kerap untuk mengemas, memecah, menyusun dan menambah butiran pada kad, supaya ia sedia diambil. Juga dipanggil backlog grooming.","also":["backlog grooming","refinement","penghalusan"]},{"id":"sprintreview","g":"agile","word":"Semakan sprint","text":"Mesyuarat di penghujung sprint di mana pasukan menunjukkan apa yang disiapkan dan mendengar pendapat orang, untuk menentukan apa yang menyusul.","also":["semakan sprint","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Menunjukkan kerja siap yang berfungsi, secara langsung, kepada orang yang memintanya.","also":["demo","tunjuk cara"],"noTip":1},{"id":"timebox","g":"agile","word":"Kotak masa","text":"Jumlah masa tetap untuk sesuatu. Apabila habis, anda berhenti, walaupun tidak semuanya siap.","also":["kotak masa","timebox","timeboxed"]},{"id":"velocity","g":"agile","word":"Halaju","text":"Berapa banyak kerja yang biasanya disiapkan pasukan dalam satu sprint, digunakan untuk merancang berapa banyak yang diambil lain kali. Ia bukan markah untuk betapa kuat orang bekerja.","also":["halaju pasukan","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Kapasiti","text":"Berapa banyak kerja yang boleh diambil pasukan dalam satu tempoh, selepas cuti dan tugas lain.","noTip":1},{"id":"burndown","g":"agile","word":"Carta burndown","text":"Carta kerja yang tinggal dalam sprint yang menurun hari demi hari. Jika garisnya kekal mendatar, ada sesuatu yang tersekat.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Carta burnup","text":"Carta kerja siap yang meningkat dari semasa ke semasa, di sebelah jumlah yang dirancang, supaya anda dapat melihat bila anda akan sampai.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Papan Kanban","text":"Papan itu sendiri: satu lajur bagi setiap peringkat kerja, dengan kad bergerak merentasinya.","also":["papan Kanban","Kanban board"]},{"id":"pullsys","g":"agile","word":"Sistem tarik","text":"Cara bekerja di mana kerja baharu hanya bermula apabila seseorang ada ruang untuk mengambilnya, bukannya ditolak ke atas pinggan yang sudah penuh.","also":["berasaskan tarikan","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Aliran","text":"Betapa lancar kerja bergerak merentasi papan. Aliran yang baik bermakna kad terus bergerak dan bukannya bertimbun.","also":["aliran kerja","flow"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Berapa lama masa dari seseorang meminta sesuatu sehingga ia siap.","also":["lead time","lead times","masa penyiapan"]},{"id":"cycletime","g":"agile","word":"Masa kitaran","text":"Berapa lama sesuatu kad mengambil masa dari kerja benar-benar bermula padanya sehingga ia siap.","also":["masa kitaran","cycle time"]},{"id":"throughput","g":"agile","word":"Daya pemprosesan","text":"Berapa banyak kad yang disiapkan dalam seminggu, atau dalam apa-apa tempoh tetap.","also":["kadar daya pemprosesan","throughput"]},{"id":"bottleneck","g":"agile","word":"Kesesakan","text":"Satu peringkat di mana kerja bertimbun dan memperlahankan segala yang di belakangnya, seperti leher botol yang sempit.","also":["kesesakan","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Lorong renang","text":"Baris merentasi papan yang mengumpulkan kad satu jenis, seperti kerja mendesak atau kad satu pasukan.","also":["lorong renang","swimlane","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Cara bekerja yang membuang pembaziran (apa-apa yang tidak membantu pelanggan) dan memastikan kerja terus mengalir."},{"id":"waste","g":"agile","word":"Pembaziran","text":"Dalam Lean, apa-apa yang memerlukan usaha tetapi tidak membantu pelanggan, seperti menunggu, kerja semula atau membina benda yang tiada siapa guna.","noTip":1},{"id":"kaizen","g":"agile","word":"Penambahbaikan berterusan","text":"Menjadi sedikit lebih baik sepanjang masa melalui perubahan kecil yang berkala, kemudian menyemak sama ada ia membantu. Retro ialah salah satu caranya. Juga dipanggil kaizen.","also":["kaizen","penambahbaikan berterusan"]},{"id":"selforg","g":"agile","word":"Pasukan mengurus sendiri","text":"Pasukan yang memutuskan sendiri bagaimana hendak melakukan kerja, bukannya diberitahu langkah demi langkah.","also":["mengurus sendiri","pasukan swa-urus","self-organising team"]},{"id":"crossfunc","g":"agile","word":"Pasukan merentas fungsi","text":"Pasukan yang mempunyai semua kemahiran yang diperlukan untuk menyiapkan kerja sendiri, seperti reka bentuk, pembinaan dan ujian.","also":["pasukan pelbagai fungsi","cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Kajian ringkas dalam masa yang dihadkan untuk menjawab sesuatu soalan sebelum komited kepada kerja sebenar.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Kerja semula","text":"Melakukan kerja lagi kerana ia tidak betul pada kali pertama.","also":["rework","mengulang kerja"]},{"id":"safe","g":"agile","word":"Agile berskala (SAFe)","text":"Cara menggunakan Agile merentasi banyak pasukan dalam organisasi besar. SAFe (Scaled Agile Framework) ialah satu contoh yang terkenal.","also":["Agile berskala","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folder kod projek bersama sejarah penuh commitnya. Ia boleh berada di komputer anda, di GitHub, atau kedua-duanya.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Satu barisan kerja berasingan dalam kod, supaya perubahan boleh dibuat tanpa menyentuh versi utama.","also":["branch","cabang"]},{"id":"commit","g":"build","word":"Commit","text":"Syot kilat kod yang disimpan, dengan nota ringkas tentang apa yang berubah. Anda sentiasa boleh kembali kepadanya.","also":["commit","komit"]},{"id":"push","g":"build","word":"Push","text":"Menghantar syot kilat tersimpan anda (commit) dari komputer ini ke salinan kongsi dalam talian, seperti GitHub, supaya ia disandarkan dan orang lain boleh mendapatkannya."},{"id":"merge","g":"build","word":"Merge","text":"Menggabungkan perubahan daripada satu branch ke dalam branch lain, biasanya kembali ke versi utama."},{"id":"pr","g":"build","word":"Pull request","text":"Meminta perubahan sesuatu branch disemak dan digabungkan ke dalam versi utama. Sesetengah laman menyebutnya merge request.","also":["PR","PRs","permintaan gabung","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Mengemaskan kod tanpa mengubah apa yang dilakukannya: fail lebih kecil, nama lebih jelas, kurang pengulangan."},{"id":"bug","g":"build","word":"Bug","text":"Sesuatu yang tidak berfungsi seperti sepatutnya.","also":["bug","pepijat"]},{"id":"peerreview","g":"build","word":"Semakan rakan sekerja","text":"Sepasang mata kedua: seseorang selain penulisnya menyemak kerja itu sebelum ia sampai kepada anda, supaya lebih sedikit kesilapan terlepas. Dalam AI-gile, AI lain menyemak setiap kad.","also":["semakan kod","peer review","code review"]},{"id":"code","g":"build","word":"Kod","text":"Arahan bertulis yang memberitahu komputer apa yang perlu dilakukan. Juga dipanggil kod sumber.","also":["kod sumber","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Bahasa pengaturcaraan","text":"Bahasa untuk menulis kod, seperti JavaScript, Python atau Java. Setiap satu sesuai untuk kerja yang berbeza.","also":["bahasa pengaturcaraan","programming language"]},{"id":"developer","g":"build","word":"Pembangun (dev)","text":"Orang yang menulis dan mengubah kod. Juga dipanggil pengaturcara atau jurutera perisian.","also":["pembangun","developer","pengaturcara","programmer","jurutera perisian","software engineer"]},{"id":"software","g":"build","word":"Perisian","text":"Program yang berjalan pada komputer dan telefon, berbanding mesin itu sendiri (perkakasan).","noTip":1},{"id":"app","g":"build","word":"Aplikasi","text":"Singkatan bagi aplikasi: program yang digunakan orang untuk menyiapkan sesuatu, pada telefon, komputer atau dalam pelayar web.","also":["app","apl","aplikasi"],"noTip":1},{"id":"webapp","g":"build","word":"Aplikasi web","text":"Aplikasi yang berjalan dalam pelayar web, jadi tiada apa yang perlu dipasang.","also":["aplikasi web","web apps","web application"]},{"id":"frontend","g":"build","word":"Bahagian hadapan","text":"Bahagian aplikasi yang anda lihat dan klik: skrin, butang dan perkataan, selalunya dalam pelayar anda.","also":["front end","front-end","frontend","hujung depan"]},{"id":"backend","g":"build","word":"Bahagian belakang","text":"Bahagian di sebalik tabir sesebuah aplikasi yang menyimpan data dan melakukan kerja apabila anda mengklik sesuatu, seperti menyemak kata laluan anda.","also":["back end","back-end","backend","hujung belakang"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Bekerja pada bahagian hadapan dan bahagian belakang sekali gus.","also":["full-stack","tindanan penuh"]},{"id":"ui","g":"build","word":"Antara muka pengguna (UI)","text":"Apa yang dilihat dan digunakan seseorang di skrin: susun atur, butang, menu dan teks.","also":["UI","user interface","antara muka pengguna"]},{"id":"ux","g":"build","word":"Pengalaman pengguna (UX)","text":"Bagaimana rasanya menggunakan sesuatu: mudah, jelas dan menyenangkan, atau mengelirukan dan lambat.","also":["UX","user experience","pengalaman pengguna"]},{"id":"accessibility","g":"build","word":"Kebolehcapaian (a11y)","text":"Membuat sesuatu boleh digunakan oleh semua orang, termasuk mereka yang tidak dapat melihat dengan baik, tidak dapat menggunakan tetikus atau menggunakan pembaca skrin.","also":["a11y","accessibility","aksesibiliti"]},{"id":"responsive","g":"build","word":"Reka bentuk responsif","text":"Membuat halaman muat dan berfungsi dengan baik pada mana-mana saiz skrin, dari telefon hingga monitor besar.","also":["responsif","responsive design"]},{"id":"designsys","g":"build","word":"Sistem reka bentuk","text":"Kit bersama yang mengandungi warna, fon, butang dan peraturan, supaya setiap skrin kelihatan dan berfungsi dengan cara yang sama.","also":["sistem reka bentuk","design system","design systems"]},{"id":"architecture","g":"build","word":"Seni bina","text":"Bentuk keseluruhan sesebuah sistem: apa bahagian utamanya dan bagaimana ia berinteraksi antara satu sama lain."},{"id":"database","g":"build","word":"Pangkalan data (DB)","text":"Simpanan maklumat yang tersusun, seperti hamparan yang sangat berkuasa yang boleh dibaca dan diubah oleh aplikasi.","also":["pangkalan data","database","databases","DB"]},{"id":"schema","g":"build","word":"Skema pangkalan data","text":"Susun atur pangkalan data: jadual maklumat apa yang ada dan apa yang masuk dalam setiap satu.","also":["skema","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Singkatan bagi bahasa pertanyaan berstruktur: bahasa yang digunakan untuk meminta banyak pangkalan data memberikan maklumat atau mengubahnya.","also":["Structured Query Language","bahasa pertanyaan berstruktur"]},{"id":"data","g":"build","word":"Data","text":"Maklumat yang disimpan oleh komputer, seperti nama, pesanan atau tetapan.","also":["set data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Pelayan","text":"Komputer yang sentiasa hidup dan menjawab permintaan daripada komputer lain, seperti menghantar halaman web apabila anda melawatinya.","also":["pelayan","server","servers"]},{"id":"client","g":"build","word":"Klien","text":"Pihak yang meminta sesuatu, biasanya pelayar atau aplikasi anda, yang berhubung dengan pelayan. Dalam perniagaan ia juga bermaksud pelanggan.","also":["klien","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Singkatan bagi antara muka pengaturcaraan aplikasi: menu tetap bagi permintaan yang boleh dibuat satu program kepada yang lain, seperti meminta perkhidmatan cuaca memberi ramalan hari ini.","also":["APIs","application programming interface","antara muka pengaturcaraan aplikasi"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Satu item pada menu API: alamat web yang boleh dipanggil oleh program untuk mendapatkan atau menghantar sesuatu.","also":["endpoints","titik akhir"]},{"id":"integration","g":"build","word":"Integrasi","text":"Menghubungkan dua sistem supaya ia berfungsi bersama, seperti kedai anda menghantar pesanan ke perisian akaun anda.","also":["integrasi","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Mesej yang dihantar secara automatik oleh satu sistem kepada sistem lain sebaik sahaja sesuatu berlaku, seperti “bayaran diterima”.","also":["webhooks"]},{"id":"library","g":"build","word":"Pustaka","text":"Kod siap pakai yang ditulis orang lain yang boleh anda gunakan semula daripada menulisnya sendiri.","also":["pustaka","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Rangka kerja","text":"Struktur siap sedia untuk membina aplikasi yang menentukan banyak tentang susun atur kod, seperti rangka rumah yang anda isi.","also":["rangka kerja","framework","frameworks"]},{"id":"sdk","g":"build","word":"Kit pembangunan perisian (SDK)","text":"Kotak alat, kod dan contoh untuk membina perisian bagi satu platform atau perkhidmatan.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Kebergantungan perisian","text":"Pustaka atau alat yang diperlukan kod anda untuk berfungsi. Memastikannya sentiasa dikemas kini penting untuk keselamatan.","also":["kebergantungan perisian","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pakej","text":"Himpunan kod siap pakai yang boleh anda pasang dan gunakan dalam projek.","also":["pakej","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pengurus pakej","text":"Alat yang mengambil dan mengemas kini pakej yang diperlukan oleh kod anda. npm ialah salah satu yang biasa.","also":["pengurus pakej","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Alat yang paling banyak digunakan untuk menyimpan sejarah perubahan kod, sebagai commit dan branch."},{"id":"github","g":"build","word":"GitHub","text":"Laman web yang menyimpan repo Git dalam talian, supaya pasukan boleh berkongsi kod, menyemak perubahan dan menjejak kerja."},{"id":"vcs","g":"build","word":"Kawalan versi","text":"Menyimpan sejarah penuh setiap perubahan pada fail, supaya anda boleh melihat siapa mengubah apa dan kembali jika perlu. Git melakukan perkara ini.","also":["kawalan sumber","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Klon","text":"Membuat salinan penuh sesebuah repo untuk diri anda sendiri, bersama sejarahnya, pada komputer anda.","also":["klon","mengklon","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Mengambil commit terkini daripada salinan kongsi (seperti GitHub) ke komputer anda. Lawan kepada push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch utama","text":"Versi rasmi kod yang menjadi asas kerja semua orang, selalunya dipanggil main atau master.","also":["main branch","master branch","cabang utama"]},{"id":"conflict","g":"build","word":"Konflik merge","text":"Apabila dua perubahan menyentuh baris yang sama dengan cara berbeza, jadi komputer tidak dapat menggabungkannya dan seseorang perlu memilih.","also":["konflik gabungan","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Paparan yang menunjukkan dengan tepat apa yang berubah antara dua versi: baris yang ditambah dan baris yang dibuang.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Salinan anda sendiri bagi repo orang lain, yang boleh anda ubah tanpa menjejaskan repo mereka.","also":["forks","forked"]},{"id":"script","g":"build","word":"Skrip","text":"Program pendek yang melakukan satu kerja dengan sendirinya, seperti mengemas fail atau memulakan aplikasi.","also":["skrip","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (binaan)","text":"Menukar kod kepada sesuatu yang sedia dijalankan, atau hasil siap jalan itu sendiri.","also":["binaan","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompil","text":"Menterjemah kod yang ditulis manusia kepada bentuk yang boleh terus dijalankan oleh komputer.","also":["kompil","mengompil","compile","compiler"]},{"id":"cli","g":"build","word":"Baris perintah (CLI)","text":"Tetingkap teks di mana anda menaip arahan untuk komputer dan bukannya mengklik. Juga dipanggil terminal.","also":["baris perintah","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Konfigurasi (config)","text":"Tetapan yang mengawal bagaimana perisian bertindak, disimpan berasingan daripada kod supaya mudah diubah.","also":["config","konfigurasi","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Pemboleh ubah persekitaran","text":"Tetapan yang diberikan kepada program semasa ia bermula, selalunya digunakan untuk alamat atau kata laluan supaya tidak ditulis dalam kod.","also":["pemboleh ubah persekitaran","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Penyahpepijatan","text":"Memburu sebab sesuatu tidak berfungsi, dan membetulkannya.","also":["nyahpepijat","debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Pengaturcaraan berpasangan","text":"Dua orang (atau seorang dan satu AI) mengusahakan kod yang sama bersama-sama, seorang menaip dan seorang menyemak.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Dokumentasi (docs)","text":"Penerangan bertulis tentang cara sesuatu berfungsi atau cara menggunakannya.","also":["dokumentasi","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Fail pertama untuk dibaca dalam repo: apa projek itu dan bagaimana menjalankannya.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistem warisan","text":"Sistem lama yang masih digunakan dan sukar diubah, selalunya kerana hanya sedikit orang yang masih memahaminya.","also":["sistem warisan","kod warisan","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Hutang teknikal","text":"Jalan pintas yang menjimatkan masa sekarang tetapi melambatkan perubahan kemudian, seperti pinjaman yang menimbun faedah. Refactoring melunaskannya.","also":["hutang teknikal","technical debt","tech debt"]},{"id":"test","g":"test","word":"Ujian","text":"Semakan bahawa sesuatu berfungsi seperti sepatutnya. Sesetengah ujian dijalankan komputer sendiri setiap kali kod berubah; yang lain ialah anda mencuba kad siap sebelum anda menerimanya.","also":["ujian","uji","test"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Singkatan bagi jaminan kualiti: semua yang dilakukan untuk memastikan kerja betul sebelum dilancarkan. Dalam AI-gile itu bermakna semakan automatik: apabila QA merah, sesuatu gagal, dan ia tidak boleh dilancarkan sehingga dibetulkan.","also":["semakan kualiti"]},{"id":"testpile","g":"test","word":"Longgokan ujian","text":"Kad siap yang menunggu untuk anda cuba, satu demi satu. Terima satu atau hantar balik dengan nota, dan yang seterusnya muncul.","also":["timbunan ujian"]},{"id":"autotest","g":"test","word":"Ujian automatik","text":"Semakan yang dijalankan komputer dengan sendirinya setiap kali kod berubah, untuk mengesan kesilapan awal.","also":["ujian automatik","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ujian manual","text":"Seseorang mencuba kerja itu sendiri secara manual untuk melihat sama ada ia berfungsi seperti sepatutnya.","also":["ujian manual","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Ujian unit","text":"Semakan automatik kecil bagi satu bahagian kod yang sangat kecil secara berasingan.","also":["ujian unit","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Ujian integrasi","text":"Semakan bahawa beberapa bahagian berfungsi dengan betul bersama-sama, bukan satu demi satu sahaja.","also":["ujian integrasi","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Ujian hujung ke hujung (E2E)","text":"Ujian yang bertindak seperti pengguna sebenar dari awal hingga akhir, seperti mendaftar, membeli dan membayar.","also":["E2E","end-to-end tests","ujian hujung ke hujung"]},{"id":"uat","g":"test","word":"Ujian penerimaan pengguna (UAT)","text":"Orang yang meminta kerja itu mencubanya sendiri dan menyatakan sama ada ia melakukan apa yang mereka perlukan. Longgokan ujian AI-gile ialah versinya.","also":["UAT","acceptance testing","ujian penerimaan"]},{"id":"regression","g":"test","word":"Regresi","text":"Sesuatu yang dahulu berfungsi tetapi rosak selepas perubahan. Ujian regresi menyemak bahawa perkara lama masih berfungsi.","also":["regresi","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Ujian asap","text":"Semakan yang sangat pantas bahawa perkara utama berfungsi langsung, contohnya sebaik sahaja perubahan dilancarkan. Jika gagal, berhenti dan siasat.","also":["ujian asap","smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Ujian penerokaan","text":"Mencuba produk dengan bebas dan menyelidikinya dengan pelbagai cara, untuk mencari masalah yang terlepas oleh semakan yang dirancang.","also":["ujian penerokaan","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Kes ujian","text":"Satu senario bertulis untuk dicuba: langkah-langkahnya, dan apa yang sepatutnya berlaku.","also":["kes ujian","test case","test cases"]},{"id":"coverage","g":"test","word":"Liputan ujian","text":"Berapa banyak kod yang disemak oleh ujian automatik. Lebih banyak biasanya lebih selamat, tetapi liputan tinggi sahaja tidak membuktikan ia berfungsi dengan baik.","also":["liputan ujian","test coverage","code coverage","liputan kod"]},{"id":"testdata","g":"test","word":"Data ujian","text":"Maklumat contoh rekaan yang digunakan semasa menguji, supaya butiran peribadi orang sebenar tidak terdedah.","also":["data ujian","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Kes tepi","text":"Keadaan luar biasa di batas, seperti borang kosong atau nama yang ada apostrof, yang sering menyebabkan sesuatu rosak.","also":["kes tepi","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Laluan lancar (happy path)","text":"Laluan biasa di mana semuanya berjalan lancar. Pengujian yang baik juga mencuba laluan yang tidak lancar."},{"id":"perftest","g":"test","word":"Ujian prestasi","text":"Menyemak betapa pantas sesuatu dan betapa baik ia menghadapi tekanan.","also":["ujian prestasi","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Ujian beban","text":"Menyemak bagaimana sesebuah sistem menghadapi keadaan apabila ramai orang menggunakannya serentak.","also":["ujian beban","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Ujian keselamatan","text":"Mencari kelemahan yang boleh membenarkan seseorang menyalahgunakan sistem atau melihat apa yang tidak sepatutnya.","also":["ujian keselamatan","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Ujian kebolehcapaian","text":"Menyemak bahawa orang dengan keupayaan berbeza boleh menggunakan produk itu, termasuk dengan pembaca skrin atau papan kekunci sahaja.","also":["ujian kebolehcapaian","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Semakan automatik yang mengesan kemungkinan kesilapan dan gaya yang bersepah dalam kod, seperti penyemak ejaan untuk program.","also":["linter","lint"]},{"id":"static","g":"test","word":"Analisis statik","text":"Menyemak kod untuk masalah dengan membacanya secara automatik, tanpa menjalankannya.","also":["analisis statik","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Ujian tidak stabil","text":"Ujian yang kadangkala lulus dan kadangkala gagal tanpa sebab yang jelas, jadi ia tidak boleh dipercayai sepenuhnya.","also":["ujian tidak stabil","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Hasilkan semula (repro)","text":"Membuat pepijat berlaku semula dengan sengaja dengan mengikut langkah yang sama, supaya ia boleh dikaji dan dibaiki. Menulis langkah-langkah itu ialah bahagian paling berguna dalam laporan pepijat.","also":["repro","reproduce","steps to reproduce","langkah untuk menghasilkan semula"]},{"id":"severity","g":"test","word":"Tahap keterukan","text":"Betapa teruk kesan sesuatu masalah, dari gangguan kecil hingga segala-galanya terhenti.","also":["tahap keterukan","keterukan","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Menyalin versi baharu perisian ke komputer yang menjalankannya, seperti salinan ujian atau perkhidmatan langsung."},{"id":"release","g":"change","word":"Keluaran","text":"Satu himpunan kerja siap yang dinamakan dan dilancarkan bersama, dengan nota ringkas tentang apa yang berubah. 🚀 Keluaran menulis nota itu daripada kad yang selesai.","also":["keluaran","release"]},{"id":"rollback","g":"change","word":"Buat asal","text":"Kembali ke versi terakhir yang berfungsi apabila yang baharu menimbulkan masalah. Dalam AI-gile, Roll back mengumpulkan langkah buat asal yang ditulis pada setiap perubahan ke dalam satu senarai semak.","also":["rollback","dibuat asal"]},{"id":"live","g":"change","word":"Live","text":"Versi sebenar yang digunakan orang, berbanding salinan untuk mencuba sesuatu. Pembangun juga memanggilnya production (produksi).","also":["langsung","produksi","production"],"noTip":1},{"id":"change","g":"change","word":"Perubahan","text":"Perubahan yang dirancang pada sesuatu yang diharapkan orang, ditulis dahulu: apa, kenapa, risikonya, bila, dan cara membatalkannya. Mulakan dengan 🔀 Bangkitkan perubahan.","also":["permintaan perubahan"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Sesuatu yang boleh tersilap, diberi skor ikut betapa mungkin dan betapa teruk ia. ⚠️ Risiko menyimpannya dalam satu senarai, skor tertinggi dahulu, setiap satu dengan tarikh untuk dilihat semula.","also":["daftar risiko","berisiko"]},{"id":"chgwin","g":"change","word":"Tetingkap perubahan","text":"Masa apabila perubahan boleh dilancarkan, seperti petang Selasa yang tenang. Di luar tetingkap, kad perubahan tidak boleh diselesaikan, kecuali jika ia kecemasan.","also":["tetingkap"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Semakan terakhir sebelum perubahan dilancarkan: setiap orang yang perlu meluluskan mengatakan Go atau No go. Ia hanya diteruskan apabila semua orang mengatakan Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Kelulusan","text":"Menunggu \"ya\" sebelum kerja bermula. Kad yang dibangkitkan oleh rakan, atau perubahan, menunggu dalam ✅ Kelulusan sehingga anda meluluskan atau menolaknya.","also":["diluluskan"]},{"id":"quiettime","g":"change","word":"Waktu rehat","text":"Tempoh masa, seperti semasa siaran langsung, demo atau semalaman, apabila tiada apa dilancarkan. Pasukan terus bekerja dan menguji, tetapi pelancaran menunggu sehingga ia tamat. Di tempat lain ia dipanggil pembekuan perubahan (change freeze).","also":["waktu tenang","pembekuan perubahan","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Cara bekerja di mana orang yang membina perisian dan orang yang menjalankannya bekerja sebagai satu pasukan, dengan banyak automasi, supaya perubahan dilancarkan dengan kerap dan selamat."},{"id":"cicd","g":"change","word":"CI/CD (integrasi dan penghantaran berterusan)","text":"Perubahan semua orang digabungkan ke dalam versi utama dengan kerap dan disemak secara automatik setiap kali (integrasi berterusan), supaya perisian sentiasa sedia dilancarkan hanya dengan menekan butang (penghantaran berterusan).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","integrasi berterusan","penghantaran berterusan"]},{"id":"contdeploy","g":"change","word":"Deployment berterusan","text":"Satu langkah lebih jauh daripada penghantaran berterusan: setiap perubahan yang lulus semakan dilancarkan secara automatik, tanpa butang untuk ditekan.","also":["deployment berterusan","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Siri langkah automatik yang dilalui sesuatu perubahan dalam perjalanannya untuk dilancarkan, seperti build, uji, kemudian deploy.","also":["saluran paip","pipeline","pipelines"]},{"id":"environment","g":"change","word":"Persekitaran","text":"Satu salinan sistem yang berasingan untuk satu tujuan, seperti satu untuk membina, satu untuk menguji dan satu lagi yang dilancarkan (live).","also":["persekitaran","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Persekitaran pembangunan","text":"Salinan tempat pembangun bekerja, selalunya pada komputer sendiri, di mana merosakkan sesuatu tidak merugikan sesiapa.","also":["persekitaran pembangunan","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Persekitaran ujian","text":"Salinan sistem yang berasingan yang digunakan khusus untuk menguji, supaya perkhidmatan sebenar tidak disentuh.","also":["persekitaran ujian","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Salinan terakhir yang disediakan sama seperti persekitaran langsung (live), untuk semakan akhir sebelum perubahan dilancarkan.","also":["staging environment","persekitaran staging"]},{"id":"artifact","g":"change","word":"Artifak binaan","text":"Fail atau himpunan yang dihasilkan oleh binaan, sedia untuk disimpan, disemak atau dilancarkan.","also":["artifak binaan","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Pembetulan segera yang dilancarkan dengan cepat, di luar rancangan biasa, kerana sesuatu yang penting rosak.","also":["hotfixes","pembetulan segera"]},{"id":"patch","g":"change","word":"Tampalan","text":"Kemas kini kecil yang membetulkan pepijat atau menutup lubang keselamatan. Memasang tampalan keselamatan dengan segera adalah penting.","also":["tampalan","patch","patches","security patch","security patches","tampalan keselamatan"]},{"id":"version","g":"change","word":"Nombor versi","text":"Label seperti 2.4.1 yang menyatakan keluaran mana yang anda ada. Selalunya nombor pertama berubah untuk perubahan besar dan yang terakhir untuk pembetulan kecil.","also":["nombor versi","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Nota keluaran","text":"Senarai ringkas dan jelas tentang apa yang berubah dalam sesuatu keluaran, untuk orang yang menggunakannya, termasuk pembetulan dan had yang diketahui. Juga dipanggil changelog.","also":["nota keluaran","release notes","changelog","change log","log perubahan"]},{"id":"flag","g":"change","word":"Bendera ciri","text":"Suis hidup dan mati untuk sesuatu ciri, supaya kerja baharu boleh dilancarkan secara tersembunyi dan dihidupkan (atau dimatikan semula) tanpa keluaran baharu.","also":["bendera ciri","feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Membetulkan keluaran yang buruk dengan segera mengeluarkan versi baharu yang telah dibetulkan dan bukannya kembali kepada yang lama.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Keluaran kenari","text":"Melancarkan perubahan kepada sekumpulan kecil dahulu, dan kepada semua orang hanya selepas ia kelihatan baik. Dinamakan sempena burung kenari yang dibawa pelombong ke bawah tanah sebagai amaran awal.","also":["keluaran kenari","canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Deployment biru-hijau","text":"Menyimpan dua salinan sistem langsung dan menukar orang kepada yang baharu sekali gus, supaya anda boleh terus bertukar balik jika ada masalah.","also":["deployment biru-hijau","blue-green","blue-green deployment","blue green deployment"]},{"id":"zerodown","g":"change","word":"Deployment tanpa henti","text":"Melancarkan versi baharu tanpa perkhidmatan itu pernah berhenti untuk penggunanya.","also":["deployment tanpa henti","zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Pengurusan perubahan","text":"Membantu perubahan berjaya: menimbang risiko, mendapatkan kelulusan yang betul dan memilih masa yang baik. Juga dipanggil change management.","also":["pengurusan perubahan","change enablement","change management"]},{"id":"cab","g":"change","word":"Lembaga penasihat perubahan (CAB)","text":"Kumpulan yang menyemak perubahan penting dan bersetuju sama ada dan bila ia boleh diteruskan.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Perubahan piawai","text":"Perubahan berisiko rendah yang dibuat dengan cara yang sama dan terbukti setiap kali, jadi ia diluluskan terlebih dahulu.","also":["perubahan piawai","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Perubahan biasa","text":"Perubahan yang perlu disemak dan diluluskan sebelum diteruskan.","also":["perubahan biasa","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Perubahan kecemasan","text":"Perubahan yang mesti berlaku serta-merta untuk membetulkan atau mencegah masalah serius, jadi kelulusannya juga lebih pantas.","also":["perubahan kecemasan","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automasi","text":"Membuat komputer melakukan kerja berulang dengan sendirinya, jadi ia lebih pantas dan dilakukan dengan cara yang sama setiap kali.","also":["automasi","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktur","text":"Mesin, rangkaian dan perkhidmatan tempat perisian berjalan.","also":["infrastruktur","infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastruktur sebagai kod (IaC)","text":"Menghuraikan pelayan dan tetapan anda dalam fail yang disimpan bersama kod, supaya ia boleh dibina semula dengan cara yang sama setiap kali.","also":["IaC","infrastructure as code","infrastruktur sebagai kod"]},{"id":"cloud","g":"change","word":"Awan","text":"Menyewa komputer, storan dan perkhidmatan daripada penyedia besar melalui internet, bukannya memiliki mesin itu sendiri.","also":["awan","cloud","the cloud","cloud computing","pengkomputeran awan"]},{"id":"provider","g":"change","word":"Penyedia awan","text":"Syarikat yang menyewakan pengkomputeran melalui internet, seperti Amazon Web Services (AWS), Microsoft Azure atau Google Cloud.","also":["penyedia awan","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting (pengehosan)","text":"Tempat aplikasi atau laman web anda tinggal dan berjalan supaya orang boleh mencapainya, biasanya disewa daripada sebuah syarikat.","also":["pengehosan","hosting","hos web"]},{"id":"domain","g":"change","word":"Nama domain","text":"Alamat web yang ditaip orang, seperti example.com. Anda menyewanya setiap tahun, jadi ia mesti diperbaharui.","also":["nama domain","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Singkatan bagi sistem nama domain: buku alamat internet, yang menukar nama seperti example.com kepada alamat komputer yang betul.","also":["domain name system","sistem nama domain"]},{"id":"container","g":"change","word":"Kontena","text":"Bungkusan tertutup yang mengandungi aplikasi dan segala yang diperlukannya, supaya ia berjalan sama pada mana-mana komputer. Docker ialah alat yang paling terkenal.","also":["kontena","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Mesin maya (VM)","text":"Komputer pura-pura yang berjalan di dalam komputer sebenar, supaya satu mesin besar boleh bertindak sebagai banyak mesin.","also":["VM","VMs","virtual machine","virtual machines","mesin maya"]},{"id":"serverless","g":"change","word":"Tanpa pelayan","text":"Menjalankan kod tanpa menjaga sebarang pelayan sendiri: penyedia menjalankannya apabila perlu dan anda membayar untuk apa yang anda guna."},{"id":"lb","g":"change","word":"Pengimbang beban","text":"Sesuatu yang mengagihkan pelawat ke beberapa pelayan, supaya tiada satu pun yang terlalu terbeban.","also":["pengimbang beban","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Simpanan keputusan terkini yang berguna dan disimpan dekat, supaya benda yang sama tidak perlu diambil atau dikira semula. Mengosongkannya boleh membetulkan halaman yang kelihatan lapuk.","also":["caches","caching","cached","cache memori","memori sorok"]},{"id":"cdn","g":"change","word":"Rangkaian penghantaran kandungan (CDN)","text":"Set pelayan di seluruh dunia yang menyimpan salinan halaman dan gambar anda berhampiran pelawat, supaya ia dimuatkan dengan pantas.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrasi","text":"Memindahkan data atau sistem daripada persediaan lama kepada yang baharu, atau mengubah susun atur pangkalan data dengan berhati-hati.","also":["migrasi","migration","migrations","database migration","migrasi pangkalan data"]},{"id":"service","g":"run","word":"Perkhidmatan","text":"Sesuatu yang anda bina dan diharapkan orang, seperti laman web atau aplikasi, dijaga supaya terus berfungsi. Tandakan “Projek ini ialah perkhidmatan” dan nyatakan apa yang ditawarkannya, siapa yang menggunakannya dan siapa yang on-call.","also":["perkhidmatan"]},{"id":"uptimepct","g":"run","word":"Uptime (masa aktif)","text":"Berapa banyak masa sesuatu perkhidmatan berfungsi, biasanya sebagai peratusan. 99.9% masih membenarkan kira-kira 43 minit terhenti sebulan.","also":["peratusan uptime","uptime percentage","masa aktif","peratusan masa aktif"]},{"id":"uptime","g":"run","word":"Semakan uptime","text":"Semakan automatik, setiap beberapa minit, bahawa perkhidmatan anda masih menjawab. Jika ia gagal beberapa kali berturut-turut, AI-gile membuka kad insiden dengan sendirinya.","also":["semakan masa aktif","uptime checks","uptime check"]},{"id":"statuspage","g":"run","word":"Halaman status","text":"Halaman awam yang menunjukkan sama ada perkhidmatan berfungsi (hijau, jingga atau merah) dengan berita terkini, supaya pengguna boleh menyemak sendiri dan tidak perlu bertanya.","also":["halaman status"]},{"id":"desk","g":"run","word":"Meja perkhidmatan","text":"Tempat masuknya soalan dan laporan daripada orang yang menggunakan perkhidmatan anda. AI-gile mengasingkan setiap satu sebagai permintaan, insiden atau idea, dan memberitahu jika ia kelihatan seperti sesuatu yang sudah dilaporkan.","also":["meja-meja perkhidmatan","meja bantuan","helpdesk"]},{"id":"svcrequest","g":"run","word":"Permintaan perkhidmatan","text":"Seseorang meminta sesuatu yang biasa, seperti akaun baharu atau sedikit bantuan, bukan melaporkan sesuatu yang rosak. Ia menunggu gilirannya; insiden didahulukan.","also":["permintaan-permintaan perkhidmatan"]},{"id":"incident","g":"run","word":"Insiden","text":"Sesuatu yang rosak atau tidak berfungsi dengan betul untuk orang yang menggunakannya sekarang, seperti laman web terhenti atau sangat perlahan. Kad insiden 🔥 memotong giliran: memulihkannya didahulukan.","also":["insiden"]},{"id":"major","g":"run","word":"Insiden besar","text":"Insiden yang besar: ramai orang terjejas, atau wang atau data berisiko. Satu butang meletakkan semua pasukan padanya (swarm), mengejutkan sesiapa yang on-call dan meminta kemas kini status setiap 30 minit.","also":["insiden utama"]},{"id":"oncall","g":"run","word":"On-call","text":"Menjadi orang yang menjawab apabila sesuatu rosak, walaupun pada waktu malam. Setiap perkhidmatan ada ahli pasukan on-call yang dikejutkan dahulu untuk insidennya.","also":["on call","bertugas atas panggilan"]},{"id":"replyby","g":"run","word":"Tempoh balas","text":"Berapa lama kad boleh menunggu jawapan pertama, contohnya sejam untuk insiden. Selepas itu ia mendapat jam merah, supaya tiada apa-apa dilupakan secara senyap. Juga dipanggil sasaran respons.","also":["sasaran respons","sasaran tindak balas"]},{"id":"postmortem","g":"run","word":"Pascanilai","text":"Imbasan ringkas selepas insiden: apa yang berlaku, apa yang membantu dan apa yang perlu diubah, tanpa menyalahkan sesiapa. Insiden tidak boleh ditutup tanpanya.","also":["post-mortem","postmortem","semakan pasca insiden"]},{"id":"problem","g":"run","word":"Masalah","text":"Punca tersembunyi di sebalik satu atau lebih insiden. Kad 🧩 masalah mengumpulkan insiden yang berulang, supaya puncanya ditemui dan dibetulkan untuk selamanya.","also":["masalah"],"noTip":1},{"id":"rootcause","g":"run","word":"Punca sebenar","text":"Sebab sebenar sesuatu rosak, bukan sekadar apa yang anda lihat tidak kena. Betulkan punca sebenar dan insiden itu berhenti berulang.","also":["punca utama","punca akar"]},{"id":"workaround","g":"run","word":"Penyelesaian sementara","text":"Cara memastikan sesuatu terus berfungsi sehingga pembetulan sebenar siap, seperti memulakan semula sesuatu apabila ia tersekat. Ia ditulis pada kad masalah supaya tiada siapa perlu memikirkannya semula.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Ralat diketahui","text":"Masalah yang puncanya difahami tetapi belum dibetulkan, biasanya dengan penyelesaian sementara yang ditulis. 🧩 Ralat diketahui menyenaraikannya, supaya semua orang menggunakan penyelesaian sementara itu dan bukannya menggali semula.","also":["ralat yang diketahui"]},{"id":"runbook","g":"run","word":"Runbook","text":"Arahan langkah demi langkah untuk membetulkan jenis masalah yang diketahui, supaya ia dilakukan dengan cara yang sama, dengan pantas, setiap kali. Selepas insiden besar pasukan boleh mencadangkan satu untuk anda beri OK.","also":["runbook"]},{"id":"ci","g":"run","word":"Item konfigurasi","text":"Satu perkara yang diperlukan oleh perkhidmatan anda, seperti pelayan, domain, sijil, kunci atau pembekal. 🗂️ Item konfigurasi menyenaraikannya mengikut perkhidmatan, supaya anda nampak apa yang terjejas oleh sesuatu insiden dan apa yang perlu diperbaharui atau disandarkan.","also":["item-item konfigurasi"]},{"id":"expiry","g":"run","word":"Tarikh luput","text":"Tarikh sesuatu berhenti berfungsi melainkan diperbaharui, seperti sijil keselamatan laman web atau alamat webnya. AI-gile memantau tarikh ini dan membuat satu kad untuk memperbaharui setiap satu 30 hari lebih awal, supaya tiada apa terhenti secara mengejut.","also":["tarikh-tarikh luput","luput","pemantauan luput"]},{"id":"backup","g":"run","word":"Sandaran","text":"Salinan data anda yang disimpan dari masa lalu, untuk digunakan jika sesuatu hilang atau rosak. AI-gile membuat sandaran papan anda setiap hari.","also":["backup","salinan sandaran"]},{"id":"restore","g":"run","word":"Pulihkan","text":"Mengembalikan data daripada sandaran. Sandaran hanya benar-benar berguna apabila anda tahu ia boleh dipulihkan, jadi eloklah mencubanya sekali-sekala.","also":["pemulihan","dipulihkan","restore"]},{"id":"svcreview","g":"run","word":"Semakan perkhidmatan","text":"Imbas kembali satu bulan sesuatu perkhidmatan: insiden yang dibuka dan dibaiki, berapa cepat orang mendapat jawapan, uptime dan token yang digunakan. Semakan bulanan menunjukkannya untuk setiap perkhidmatan.","also":["semakan-semakan perkhidmatan","semakan bulanan","semakan-semakan bulanan"]},{"id":"accessreview","g":"run","word":"Semakan akses","text":"Menyemak setiap 90 hari siapa yang masih boleh masuk: pautan kongsi, peranan rakan serta kata laluan dan kunci yang disimpan. Anda mengekalkan atau membuang setiap satu, supaya akses lama tidak berlarutan.","also":["semakan-semakan akses"]},{"id":"improvements","g":"run","word":"Senarai penambahbaikan","text":"Semua yang pasukan putuskan untuk diperbaiki, di satu tempat: cadangan retro, tindakan semakan dan pembaikan masalah, setiap satu dengan statusnya. Terdapat di bawah 📈 Penambahbaikan.","also":["senarai-senarai penambahbaikan","penambahbaikan"]},{"id":"tokencap","g":"run","word":"Had token","text":"Had bulanan token yang boleh digunakan oleh ejen sesuatu perkhidmatan. Pada 80% anda menerima amaran; pada 100% kerja latar mereka menunggu sehingga bulan depan atau sehingga anda menaikkan had.","also":["had-had token"]},{"id":"svcmgmt","g":"run","word":"Pengurusan perkhidmatan","text":"Segala yang terlibat dalam memastikan sesuatu perkhidmatan berguna dan berfungsi untuk orang yang bergantung kepadanya, hari demi hari.","also":["pengurusan perkhidmatan","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Panduan yang digunakan secara meluas untuk pengurusan perkhidmatan yang baik, merangkumi perkara seperti insiden, masalah dan perubahan. Nama itu dahulunya bermaksud IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Pengurusan perkhidmatan IT (ITSM)","text":"Mengendalikan teknologi sebagai perkhidmatan untuk orang, dengan cara yang jelas untuk menangani permintaan, insiden, perubahan dan penambahbaikan.","also":["ITSM"]},{"id":"managed","g":"run","word":"Perkhidmatan terurus","text":"Perkhidmatan yang dijalankan dan dijaga oleh pihak lain untuk anda, di bawah perjanjian tentang betapa baik ia mesti berfungsi.","also":["perkhidmatan terurus","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Pemilik perkhidmatan","text":"Orang yang bertanggungjawab ke atas perkhidmatan secara keseluruhan: betapa baik ia berfungsi, berapa kosnya dan bagaimana ia bertambah baik.","also":["pemilik perkhidmatan","service owner","service owners"]},{"id":"sla","g":"run","word":"Perjanjian tahap perkhidmatan (SLA)","text":"Janji bertulis kepada pelanggan tentang betapa baik sesuatu perkhidmatan akan berfungsi, seperti “hidup 99.9% masa” atau “dijawab dalam masa sejam”, selalunya dengan bayaran balik jika dilanggar.","also":["SLA","SLAs","service level agreement","perjanjian tahap perkhidmatan"]},{"id":"slo","g":"run","word":"Objektif tahap perkhidmatan (SLO)","text":"Sasaran pasukan sendiri tentang betapa baik sesuatu perkhidmatan patut berfungsi dalam sesuatu tempoh, biasanya ditetapkan sedikit lebih ketat daripada SLA untuk keselamatan.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Penunjuk tahap perkhidmatan (SLI)","text":"Ukuran sebenar yang anda semak berbanding sasaran, seperti peratusan lawatan yang dimuatkan dengan baik.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Ketersediaan","text":"Sama ada orang boleh menggunakan perkhidmatan apabila mereka memerlukannya, selalunya diukur sebagai uptime.","also":["ketersediaan","availability","high availability","ketersediaan tinggi"]},{"id":"downtime","g":"run","word":"Masa henti","text":"Masa apabila sesuatu perkhidmatan tidak berfungsi atau dimatikan, dirancang atau tidak.","also":["masa henti","downtime","down time"]},{"id":"errorbudget","g":"run","word":"Bajet ralat","text":"Sedikit kegagalan yang dibenarkan oleh sasaran kebolehharapan anda. Selagi ada baki, anda boleh mengambil risiko dengan perubahan; apabila habis, anda perlu memperlahankan langkah.","also":["bajet ralat","error budget","error budgets"]},{"id":"outage","g":"run","word":"Gangguan perkhidmatan","text":"Masa apabila sesuatu perkhidmatan terhenti atau rosak teruk untuk penggunanya.","also":["gangguan perkhidmatan","outage","outages"]},{"id":"degraded","g":"run","word":"Merosot","text":"Berfungsi, tetapi tidak dengan baik: perlahan, atau sesetengah bahagian tidak berfungsi.","also":["merosot","degraded","degraded service","perkhidmatan merosot"]},{"id":"monitoring","g":"run","word":"Pemantauan","text":"Memerhatikan sesuatu perkhidmatan secara automatik sepanjang masa, supaya masalah dikesan, sebaik-baiknya sebelum pengguna perasan.","also":["pemantauan","monitoring"]},{"id":"observability","g":"run","word":"Kebolehcerapan","text":"Betapa baik anda dapat tahu apa yang berlaku di dalam sesebuah sistem dari luar, menggunakan log, nombor dan jejaknya.","also":["kebolehcerapan","observability","o11y"]},{"id":"log","g":"run","word":"Log","text":"Catatan berterusan yang disimpan oleh program tentang apa yang sedang dilakukannya, digunakan untuk mengetahui apa yang tidak kena.","also":["logs","logging","catatan log"],"noTip":1},{"id":"trace","g":"run","word":"Jejak","text":"Rekod bagaimana satu permintaan melalui bahagian-bahagian sistem yang berbeza, langkah demi langkah, menunjukkan di mana ia menjadi perlahan.","also":["jejak","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Kependaman","text":"Berapa lama sesuatu mengambil masa untuk menjawab, seperti masa menunggu antara mengklik dan halaman muncul.","also":["kependaman","latency"]},{"id":"alert","g":"run","word":"Makluman","text":"Mesej automatik bahawa sesuatu memerlukan perhatian, seperti laman web tidak menjawab.","also":["makluman","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Keletihan makluman","text":"Apabila terlalu banyak makluman sehingga orang mula mengabaikannya, termasuk yang penting.","also":["keletihan makluman","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Papan pemuka","text":"Skrin yang menunjukkan nombor dan status paling penting sepintas lalu.","also":["papan pemuka","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Panggilan segera","text":"Menghubungi atau mengejutkan orang yang on-call dengan segera tentang sesuatu masalah.","also":["panggilan segera","paging","paged"]},{"id":"escalation","g":"run","word":"Eskalasi","text":"Membawa masuk seseorang yang lebih mahir atau berkuasa apabila sesuatu isu tidak dapat diselesaikan pada peringkat semasa, atau tidak cukup pantas.","also":["eskalasi","peningkatan isu","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triaj","text":"Menyusun isu yang masuk dengan cepat mengikut betapa mendesak dan pentingnya, supaya yang paling teruk ditangani dahulu.","also":["triaj","triage","triaged"]},{"id":"impact","g":"run","word":"Impak","text":"Betapa banyak sesuatu menjejaskan orang: berapa ramai, dan betapa teruk.","noTip":1},{"id":"urgency","g":"run","word":"Kedesakan","text":"Betapa cepat sesuatu perlu ditangani. Impak dan kedesakan bersama-sama menentukan keutamaan.","noTip":1},{"id":"plevels","g":"run","word":"Tahap keutamaan (P1, P2…)","text":"Label untuk betapa mendesak sesuatu isu. P1 paling serius dan memerlukan tindakan segera.","also":["P1","P2","P3","P4","tahap keutamaan","priority levels"]},{"id":"queue","g":"run","word":"Baris gilir tiket","text":"Senarai permintaan dan insiden yang menunggu untuk diambil.","also":["baris gilir tiket","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Barisan pertama dan kedua","text":"Peringkat sokongan: barisan pertama menerima panggilan dan membetulkan perkara mudah; barisan kedua mempunyai kemahiran lebih mendalam untuk yang lebih sukar. Juga dipanggil tier 1 dan tier 2.","also":["barisan pertama","barisan kedua","sokongan barisan pertama","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Komander insiden","text":"Satu-satunya orang yang mengetuai tindak balas terhadap sesuatu insiden, supaya semua orang tahu siapa yang memutuskan dan siapa melakukan apa.","also":["komander insiden","ketua insiden","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Masa tindak balas","text":"Berapa lama sebelum seseorang mula mengambil sesuatu permintaan atau insiden.","also":["masa tindak balas","response time","response times"]},{"id":"resolution","g":"run","word":"Masa penyelesaian","text":"Berapa lama masa yang diambil untuk menyelesaikan sepenuhnya sesuatu permintaan atau insiden, dari laporan hingga dibetulkan.","also":["masa penyelesaian","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Purata masa pemulihan (MTTR)","text":"Secara purata, berapa lama untuk menjadikan sesuatu perkhidmatan berfungsi semula selepas ia rosak. MTTR boleh membawa maksud yang sedikit berbeza, jadi nyatakan apa yang anda ukur.","also":["MTTR","mean time to recover","mean time to restore","purata masa pemulihan"]},{"id":"mtbf","g":"run","word":"Purata masa antara kegagalan (MTBF)","text":"Secara purata, berapa lama sesuatu perkhidmatan berjalan sebelum sesuatu rosak.","also":["MTBF","mean time between failures","purata masa antara kegagalan"]},{"id":"cmdb","g":"run","word":"Pangkalan data pengurusan konfigurasi (CMDB)","text":"Senarai semua item konfigurasi anda dan bagaimana ia bersambung, supaya anda boleh melihat apa bergantung pada apa.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Aset","text":"Apa-apa yang bernilai yang anda miliki atau bayar untuk menjalankan perkhidmatan, seperti komputer riba, lesen perisian atau domain.","also":["aset","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Perancangan kapasiti","text":"Memastikan akan ada cukup kuasa komputer, storan dan orang untuk apa yang akan datang.","also":["perancangan kapasiti","capacity planning","capacity plan","pelan kapasiti"]},{"id":"scaling","g":"run","word":"Penskalaan","text":"Menghadapi lebih ramai pengguna dengan memberi sebuah mesin lebih kuasa (skala ke atas) atau menambah lebih banyak mesin (skala ke luar).","also":["penskalaan","scaling","scale up","scale out","scaling up","scaling out","menskala"]},{"id":"bcp","g":"run","word":"Kesinambungan perniagaan","text":"Pelan untuk memastikan perkara penting terus berjalan apabila sesuatu yang besar berlaku, seperti kehilangan pejabat, pembekal utama atau komputer.","also":["kesinambungan perniagaan","business continuity","business continuity plan","pelan kesinambungan perniagaan"]},{"id":"dr","g":"run","word":"Pemulihan bencana (DR)","text":"Pelan dan alat untuk mendapatkan semula sesuatu perkhidmatan selepas sesuatu yang serius, seperti kehilangan seluruh pusat data.","also":["pemulihan bencana","disaster recovery","DR"]},{"id":"rto","g":"run","word":"Objektif masa pemulihan (RTO)","text":"Tempoh paling lama sesuatu perkhidmatan boleh terhenti selepas bencana sebelum ia mesti berfungsi semula.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Objektif titik pemulihan (RPO)","text":"Berapa banyak data terkini yang anda sanggup hilang, diukur dalam masa. RPO satu jam bermakna sandaran sekurang-kurangnya setiap jam.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Lewahan","text":"Mempunyai ganti yang sedia, seperti pelayan kedua, supaya satu kegagalan tidak menghentikan perkhidmatan.","also":["lewahan","redundancy","redundansi"]},{"id":"failover","g":"run","word":"Failover","text":"Beralih kepada sistem ganti secara automatik apabila sistem biasa gagal.","also":["fail over","pengalihan kegagalan","beralih ganti"]},{"id":"spof","g":"run","word":"Titik kegagalan tunggal","text":"Satu bahagian yang menjatuhkan segala-galanya bersamanya apabila ia rosak, kerana tiada ganti.","also":["titik kegagalan tunggal","single points of failure","single point of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Tetingkap penyelenggaraan","text":"Masa yang dirancang apabila sesuatu perkhidmatan boleh dijeda atau perlahan untuk penyelenggaraan, diumumkan kepada pengguna lebih awal.","also":["tetingkap penyelenggaraan","maintenance window","maintenance windows","planned maintenance","penyelenggaraan berjadual"]},{"id":"handover","g":"run","word":"Serah tugas","text":"Menyerahkan kerja, pengetahuan dan tanggungjawab kepada orang atau pasukan lain, supaya tiada apa yang tercicir.","also":["serah tugas","handover","handovers","penyerahan"]},{"id":"kb","g":"run","word":"Pangkalan pengetahuan","text":"Koleksi artikel bantuan dan jawapan, untuk pengguna dan untuk pasukan.","also":["pangkalan pengetahuan","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Kepuasan pelanggan (CSAT)","text":"Skor daripada pengguna yang menyatakan betapa gembira mereka, selalunya ditanya selepas sesuatu permintaan ditutup.","also":["CSAT","customer satisfaction","kepuasan pelanggan"]},{"id":"supplier","g":"run","word":"Pembekal","text":"Syarikat luar yang anda bergantung kepadanya, seperti penyedia hosting anda. Juga dipanggil vendor atau pihak ketiga.","also":["pembekal","supplier","suppliers","vendor","vendors","third party","pihak ketiga"],"noTip":1},{"id":"retire","g":"run","word":"Penamatan perkhidmatan","text":"Mematikan sesuatu perkhidmatan untuk selama-lamanya dengan selamat: memberitahu penggunanya, menguruskan data dan aksesnya, dan menghentikan kosnya.","also":["penamatan perkhidmatan","persaraan perkhidmatan","menamatkan perkhidmatan","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Akhir hayat (EOL)","text":"Apabila sesuatu produk berhenti menerima kemas kini atau sokongan daripada pembuatnya, jadi ia patut diganti.","also":["EOL","end of life","end-of-life","akhir hayat"]},{"id":"cybersec","g":"sec","word":"Keselamatan siber","text":"Melindungi sistem dan data daripada dicerobohi, dicuri atau dirosakkan.","also":["keselamatan siber","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Pengesahan identiti","text":"Menyemak siapa seseorang itu, biasanya dengan kata laluan atau kod. Selalunya dipendekkan kepada authn.","also":["pengesahan identiti","authentication","authn"]},{"id":"authz","g":"sec","word":"Pemberian kuasa","text":"Menyemak apa yang dibenarkan seseorang lakukan setelah anda tahu siapa dia. Selalunya dipendekkan kepada authz.","also":["pemberian kuasa","pengesahan kebenaran","authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Pengesahan berbilang faktor (MFA)","text":"Log masuk dengan dua atau lebih bukti, seperti kata laluan ditambah kod pada telefon anda. Juga dipanggil dua faktor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","pengesahan dua faktor"]},{"id":"sso","g":"sec","word":"Log masuk tunggal (SSO)","text":"Log masuk sekali untuk masuk ke banyak sistem, seperti menggunakan akaun kerja anda di mana-mana.","also":["SSO","single sign-on","log masuk sekali"]},{"id":"pwmgr","g":"sec","word":"Pengurus kata laluan","text":"Aplikasi yang mencipta kata laluan yang kuat dan mengingatinya untuk anda.","also":["pengurus kata laluan","password manager","password managers"]},{"id":"secret","g":"sec","word":"Rahsia","text":"Kata laluan, kunci atau kod persendirian lain yang digunakan program untuk masuk ke sesuatu. Ia tidak boleh dikongsi atau ditulis dalam kod.","also":["rahsia","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Kunci API","text":"Kod rahsia yang membolehkan program menggunakan API perkhidmatan lain, dan menunjukkan siapa yang menggunakan (dan membayar) untuknya.","also":["kunci API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token akses","text":"Pas sementara yang membuktikan sesebuah program dibenarkan masuk, jadi ia tidak memerlukan kata laluan anda setiap kali. Tidak sama dengan token AI.","also":["token akses","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Penyulitan","text":"Menukar maklumat kepada bentuk berkod supaya hanya orang yang mempunyai kunci yang betul boleh membacanya.","also":["penyulitan","enkripsi","encryption","encrypted","encrypt","disulitkan"]},{"id":"https","g":"sec","word":"HTTPS","text":"Cara selamat halaman web dihantar, ditunjukkan oleh ikon mangga di pelayar anda, supaya tiada sesiapa di tengah-tengah laluan dapat membaca atau mengubahnya."},{"id":"cert","g":"sec","word":"Sijil SSL/TLS","text":"Kad pengenalan digital yang membolehkan laman web membuktikan siapa ia dan menggunakan HTTPS. Ia tamat tempoh, jadi mesti diperbaharui.","also":["sijil TLS","sijil SSL","sijil","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Kebenaran","text":"Peraturan tentang siapa yang boleh melihat atau mengubah apa.","also":["kebenaran","permissions","permission","kebenaran akses"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Keistimewaan paling minimum","text":"Memberi setiap orang atau program hanya akses yang benar-benar mereka perlukan, hanya selama mereka memerlukannya.","also":["keistimewaan paling minimum","least privilege","principle of least privilege","prinsip keistimewaan minimum"]},{"id":"rbac","g":"sec","word":"Kawalan akses berasaskan peranan (RBAC)","text":"Memberi akses mengikut peranan, seperti penonton atau penyunting, dan bukannya seorang demi seorang.","also":["RBAC","role-based access","role-based access control","akses berasaskan peranan"]},{"id":"vuln","g":"sec","word":"Kerentanan","text":"Kelemahan yang boleh digunakan seseorang untuk menceroboh atau menyebabkan bahaya.","also":["kerentanan","kelemahan keselamatan","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Kelemahan yang diketahui penyerang sebelum pembuatnya sempat membetulkannya.","also":["zero-days","zero day","hari sifar"]},{"id":"malware","g":"sec","word":"Perisian hasad","text":"Perisian berbahaya, seperti virus, yang dibuat untuk merosakkan, mengintip atau mencuri.","also":["perisian hasad","malware"]},{"id":"ransomware","g":"sec","word":"Perisian tebusan","text":"Perisian hasad yang mengunci fail anda dan menuntut wang untuk membukanya. Sandaran yang baik ialah pertahanan terbaik.","also":["perisian tebusan","ransomware","ransomware attack","serangan perisian tebusan"]},{"id":"phishing","g":"sec","word":"Pancingan data","text":"Mesej palsu yang cuba memperdaya anda supaya menyerahkan kata laluan atau wang, atau membuka sesuatu yang berbahaya.","also":["pancingan data","phishing","phishing email","phishing emails","e-mel pancingan data"]},{"id":"socialeng","g":"sec","word":"Kejuruteraan sosial","text":"Memperdaya orang, bukannya komputer, supaya memberi akses, seperti panggilan palsu daripada “sokongan IT”."},{"id":"firewall","g":"sec","word":"Tembok api","text":"Pengawal yang menentukan trafik rangkaian mana yang boleh masuk atau keluar.","also":["tembok api","firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Singkatan bagi rangkaian persendirian maya: pautan peribadi yang disulitkan melalui internet, selalunya digunakan untuk mencapai sistem kerja dengan selamat.","also":["virtual private network","rangkaian persendirian maya"]},{"id":"ddos","g":"sec","word":"Penafian perkhidmatan (DoS, DDoS)","text":"Membanjiri sesuatu perkhidmatan dengan begitu banyak trafik palsu sehingga orang sebenar tidak dapat menggunakannya. DDoS bermakna ia datang daripada banyak komputer serentak.","also":["DoS","DDoS","denial of service","DDoS attack","penafian perkhidmatan","serangan DDoS"]},{"id":"pentest","g":"sec","word":"Ujian penembusan (pen test)","text":"Mengupah pakar yang dipercayai untuk cuba menceroboh, supaya kelemahan ditemui sebelum penyerang sebenar menemuinya.","also":["ujian penembusan","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Audit keselamatan","text":"Semakan teliti tentang sebaik mana sesuatu dilindungi, berdasarkan senarai amalan yang baik.","also":["audit keselamatan","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Pemodelan ancaman","text":"Memikirkan siapa yang mungkin menyerang sesuatu, bagaimana, dan apa yang anda akan lakukan untuk menghalang mereka.","also":["pemodelan ancaman","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Pelanggaran data","text":"Apabila maklumat peribadi sampai kepada orang yang tidak sepatutnya memilikinya, atau hilang atau diubah tanpa kebenaran.","also":["pelanggaran data","kebocoran data","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Data peribadi","text":"Apa-apa maklumat tentang seseorang yang boleh dikenal pasti, seperti nama, alamat e-mel atau lokasi. Juga dipanggil PII.","also":["data peribadi","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Undang-undang Eropah tentang data peribadi (UK mempunyai versinya sendiri): kumpul hanya yang anda perlukan, simpan dengan selamat, dan biarkan orang melihat atau memadam data mereka.","also":["General Data Protection Regulation","Peraturan Perlindungan Data Am"]},{"id":"dataprot","g":"sec","word":"Perlindungan data","text":"Menjaga data peribadi dengan betul dan mengikut undang-undang.","also":["perlindungan data","data protection","data protection law","undang-undang perlindungan data"]},{"id":"privacypolicy","g":"sec","word":"Dasar privasi","text":"Halaman awam yang menyatakan data peribadi apa yang anda kumpul, mengapa, dan apa yang anda lakukan dengannya.","also":["dasar privasi","polisi privasi","privacy policy","privacy statement","privacy notice","notis privasi"]},{"id":"consent","g":"sec","word":"Persetujuan","text":"“Ya” yang jelas dan bebas daripada seseorang supaya datanya digunakan dengan cara tertentu. Mereka boleh menariknya balik pada bila-bila masa.","also":["persetujuan","consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Kuki","text":"Fail kecil yang disimpan laman web dalam pelayar anda untuk mengingati perkara, seperti sudah log masuk. Sesetengahnya memerlukan persetujuan anda dahulu.","also":["kuki","cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Peminimuman data","text":"Mengumpul dan menyimpan hanya data peribadi yang benar-benar anda perlukan untuk tugas itu.","also":["peminimuman data","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Pengekalan data","text":"Berapa lama data disimpan sebelum dipadam. Menyimpannya tidak lebih lama daripada perlu adalah lebih selamat dan selalunya dikehendaki undang-undang.","also":["pengekalan data","data retention","retention period","tempoh pengekalan"]},{"id":"anon","g":"sec","word":"Penyahnamaan","text":"Mengubah data supaya tiada sesiapa boleh dikenal pasti daripadanya secara munasabah lagi.","also":["penyahnamaan","anonymisation","anonymised","anonymization","anonymous data","data tanpa nama"]},{"id":"pseudo","g":"sec","word":"Penamaan samaran","text":"Menukar nama dan butiran lain dengan kod, dengan kunci yang disimpan berasingan untuk memautkannya semula. Ia masih data peribadi.","also":["penamaan samaran","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Perjanjian pemprosesan data (DPA)","text":"Kontrak yang menyatakan bagaimana pembekal boleh mengendalikan data peribadi bagi pihak anda.","also":["DPA","data processing agreement","perjanjian pemprosesan data"]},{"id":"dpia","g":"sec","word":"Penilaian kesan perlindungan data (DPIA)","text":"Pemeriksaan teliti, sebelum anda bermula, tentang bagaimana rancangan menggunakan data peribadi boleh menjejaskan orang dan bagaimana mengurangkan risikonya.","also":["DPIA","data protection impact assessment","penilaian kesan perlindungan data"]},{"id":"auditlog","g":"sec","word":"Log audit","text":"Rekod siapa melakukan apa dan bila, supaya tindakan boleh disemak kemudian.","also":["log audit","audit log","audit logs","audit trail","jejak audit"]},{"id":"compliance","g":"sec","word":"Pematuhan","text":"Mengikut undang-undang, peraturan dan piawaian yang terpakai kepada anda, dan dapat menunjukkan bahawa anda berbuat demikian.","also":["pematuhan","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Piawaian antarabangsa yang terkenal untuk menguruskan keselamatan maklumat. Syarikat boleh mendapat pensijilan berdasarkannya.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Laporan AS, disemak oleh juruaudit luar, yang menunjukkan syarikat menjaga data pelanggan dengan betul.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Ejen","text":"AI yang mengusahakan sesuatu tugas sendirian: membaca kod, membuat perubahan, menjalankan semakan dan melapor semula. Kerjanya masih disemak.","also":["ejen","agent"]},{"id":"token","g":"ai","word":"Token","text":"Cebisan teks kecil yang dibaca dan ditulis oleh AI, kira-kira tiga perempat perkataan setiap satu. Penggunaan AI dikira dalam token, jadi makin sedikit token, makin banyak baki pelan anda.","also":["token","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Arahan kecil yang berjalan sendiri pada saat tertentu, contohnya apabila sesi AI bermula, supaya pasukan mendengar komen anda.","also":["hook","hooks"]},{"id":"ai","g":"ai","word":"Kecerdasan buatan (AI)","text":"Sistem komputer yang melakukan perkara yang biasanya kita fikir memerlukan manusia, seperti menulis, menjawab soalan atau mengenali gambar.","also":["AI","artificial intelligence","kecerdasan buatan","akal buatan"],"noTip":1},{"id":"ml","g":"ai","word":"Pembelajaran mesin (ML)","text":"Cara membuat komputer belajar corak daripada banyak contoh, bukannya memberinya peraturan tepat.","also":["ML","machine learning","pembelajaran mesin"]},{"id":"model","g":"ai","word":"Model","text":"“Otak” terlatih bagi sesebuah sistem AI, dibina dengan belajar daripada bilangan contoh yang amat banyak. Model berbeza dari segi kemahiran, kelajuan dan harga.","also":["models","AI model","model AI"],"noTip":1},{"id":"llm","g":"ai","word":"Model bahasa besar (LLM)","text":"Model AI yang dilatih dengan sejumlah besar teks, supaya ia boleh membaca dan menulis bahasa.","also":["LLM","LLMs","large language model","model bahasa besar"]},{"id":"genai","g":"ai","word":"AI generatif","text":"AI yang mencipta benda baharu, seperti teks, gambar atau kod, bukannya hanya menyusun atau mengesannya.","also":["AI generatif","generative AI","GenAI"]},{"id":"chatbot","g":"ai","word":"Bot sembang","text":"Program yang boleh anda ajak berbual dalam bahasa harian, dengan menaip atau bercakap.","also":["bot sembang","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Apa yang anda berikan kepada AI: soalan atau arahan anda, ditambah apa-apa yang anda serahkan. Prompt yang lebih jelas biasanya mendapat jawapan yang lebih baik.","also":["prompts","gesaan"]},{"id":"prompteng","g":"ai","word":"Kejuruteraan prompt","text":"Kemahiran menulis prompt yang memberi hasil yang boleh dipercayai dan berguna.","also":["kejuruteraan prompt","prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Prompt sistem","text":"Arahan latar belakang yang diterima AI sebelum perbualan bermula, menetapkan peranan dan peraturannya. Ia lebih berat daripada apa yang anda taip.","also":["prompt sistem","system prompt","system prompts","system instruction","system instructions","arahan sistem"]},{"id":"context","g":"ai","word":"Konteks","text":"Segala yang AI boleh lihat semasa ia bekerja: arahan, mesej anda, fail yang telah dibacanya dan jawapan terdahulu.","noTip":1},{"id":"ctxwin","g":"ai","word":"Tetingkap konteks","text":"Berapa banyak yang AI boleh ingat sekali gus, diukur dalam token. Melebihi had itu, bahagian yang lebih lama dibuang atau diringkaskan.","also":["tetingkap konteks","context window","context windows"]},{"id":"session","g":"ai","word":"Sesi","text":"Satu perbualan kerja dengan AI, dari mula hingga akhir. Sesi baharu bermula dengan ingatan yang segar.","also":["sesi","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Ingatan","text":"Nota yang disimpan AI antara sesi, supaya ia mengingati pilihan dan keputusan lalu anda.","noTip":1},{"id":"hallucination","g":"ai","word":"Halusinasi","text":"Apabila AI mengatakan sesuatu yang kedengaran yakin tetapi sebenarnya direka atau salah. Semak fakta yang penting.","also":["halusinasi","hallucination","hallucinations","hallucinate","hallucinates","berhalusinasi"]},{"id":"training","g":"ai","word":"Latihan","text":"Mengajar model dengan menunjukkan bilangan contoh yang amat banyak, sebelum sesiapa menggunakannya.","also":["latihan","training","trained","dilatih"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Data latihan","text":"Contoh yang dipelajari model. Pengetahuannya berhenti pada tarikh data itu dikumpulkan.","also":["data latihan","training data","training set"]},{"id":"cutoff","g":"ai","word":"Had pengetahuan","text":"Tarikh berakhirnya pengetahuan terbina dalam AI. Ia tidak akan tahu tentang perkara selepas itu melainkan ia mencarinya.","also":["had pengetahuan","knowledge cutoff","training cutoff","tarikh henti pengetahuan"]},{"id":"finetune","g":"ai","word":"Penalaan halus","text":"Latihan tambahan bagi model sedia ada dengan contoh anda sendiri, untuk menjadikannya lebih baik dalam satu tugas tertentu.","also":["penalaan halus","fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferens","text":"Model AI yang sebenarnya digunakan untuk menjawab sesuatu, bukan semasa ia dilatih.","also":["inferens","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Penggunaan alat","text":"AI boleh melakukan sesuatu, bukan sekadar bercakap: menjalankan arahan, membaca fail atau mencari di web, melalui alat yang diberikan aplikasi kepadanya.","also":["penggunaan alat","tool use","tool calling","tool call","tool calls","panggilan alat"]},{"id":"subagent","g":"ai","word":"Sub-ejen","text":"AI pembantu yang diberi kerja lebih kecil oleh AI utama, lalu menghantar hasilnya kembali.","also":["sub-ejen","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Berbilang ejen","text":"Beberapa AI bekerja bersama pada satu kerja, masing-masing dengan bahagiannya sendiri, seperti pasukan kecil.","also":["berbilang ejen","multi-agent","multi-agent system","sistem berbilang ejen"]},{"id":"autonomy","g":"ai","word":"Autonomi","text":"Berapa banyak yang AI boleh lakukan sendiri sebelum ia perlu bertanya kepada seseorang.","also":["autonomi","autonomy","autonomous","berautonomi"]},{"id":"hitl","g":"ai","word":"Manusia dalam gelung","text":"Memastikan seseorang terlibat untuk menyemak atau meluluskan apa yang AI lakukan pada saat-saat penting. Dalam AI-gile itu ialah anda.","also":["manusia dalam gelung","human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Pagar pengadang","text":"Had dan semakan yang memastikan tindakan AI selamat, seperti memerlukan kelulusan sebelum apa-apa dilancarkan. Ia mengurangkan risiko kesilapan, tetapi tidak menghapuskannya.","also":["pagar pengadang","guardrails","guardrail","pengadang keselamatan"]},{"id":"rag","g":"ai","word":"Penjanaan dipertingkat perolehan (RAG)","text":"Membenarkan AI mencari dalam dokumen anda sendiri sebelum menjawab, supaya jawapannya berdasarkan fakta anda.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Benaman","text":"Menukar teks kepada senarai nombor yang menangkap maknanya, supaya komputer boleh mencari benda yang bermakna serupa.","also":["benaman","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Pangkalan data vektor","text":"Pangkalan data yang dibina untuk mencari dalam senarai nombor itu (benaman), bagi mencari bahan yang bermakna serupa.","also":["pangkalan data vektor","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Cara biasa untuk memasang alat dan sumber data ke dalam aplikasi AI, supaya AI boleh menggunakannya.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Suhu","text":"Tetapan untuk seberapa berani jawapan AI. Rendah memberi jawapan yang lebih stabil dan boleh dijangka; tinggi memberi jawapan yang lebih pelbagai. Namun kedua-duanya tidak menjamin jawapan sentiasa betul.","also":["suhu","temperature","model temperature","suhu model"],"noTip":1},{"id":"multimodal","g":"ai","word":"Pelbagai mod","text":"Mampu bekerja dengan lebih daripada satu jenis maklumat, seperti teks, gambar dan bunyi.","also":["pelbagai mod","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Penilaian (eval)","text":"Ujian terancang tentang betapa baik AI menjawab contoh yang dipilih, supaya anda boleh membandingkan model atau prompt.","also":["eval","evals","penilaian"]},{"id":"bias","g":"ai","word":"Bias","text":"Apabila AI (atau seseorang) condong ke satu pihak secara tidak adil, selalunya kerana apa yang dipelajarinya.","also":["berat sebelah","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI yang bertanggungjawab","text":"Menggunakan AI dengan adil, selamat dan jujur, dengan orang masih bertanggungjawab ke atas hasilnya.","also":["AI yang bertanggungjawab","responsible AI","ethical AI","AI beretika"]},{"id":"injection","g":"ai","word":"Suntikan prompt","text":"Helah di mana arahan tersembunyi dalam halaman web atau fail cuba membuat AI melakukan sesuatu yang tidak diminta penggunanya.","also":["suntikan prompt","prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Had kadar","text":"Had pada berapa banyak permintaan yang boleh anda hantar kepada perkhidmatan dalam masa tertentu. Jika melebihinya, anda perlu menunggu.","also":["had kadar","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Had penggunaan","text":"Berapa banyak kerja AI yang dibenarkan pelan anda dalam satu tempoh, selepas itu ia dijeda atau kosnya bertambah.","also":["had penggunaan","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Membina perisian kebanyakannya dengan menerangkan apa yang anda mahu kepada AI dan membiarkannya menulis kod.","also":["vibe-coding","pengekodan vibe"]},{"id":"budget","g":"money","word":"Bajet","text":"Jumlah wang yang diketepikan untuk sesuatu.","also":["bajet","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Anggaran kos","text":"Tekaan terbaik tentang berapa kos sesuatu sebelum anda bermula.","also":["anggaran kos","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Pulangan atas pelaburan (ROI)","text":"Apa yang anda dapat balik berbanding apa yang anda laburkan. Jika positif, ia berbaloi.","also":["ROI","return on investment","pulangan atas pelaburan"]},{"id":"tco","g":"money","word":"Jumlah kos pemilikan (TCO)","text":"Segala yang sebenarnya dibelanjakan untuk sesuatu sepanjang hayatnya, bukan sekadar harga belian: menjalankan, sokongan, naik taraf dan akhirnya menamatkannya.","also":["TCO","total cost of ownership","jumlah kos pemilikan"]},{"id":"capex","g":"money","word":"CapEx dan OpEx","text":"CapEx ialah wang yang dibelanjakan di awal untuk benda yang anda simpan; OpEx ialah perbelanjaan berterusan, seperti bil bulanan.","also":["CapEx","OpEx","capital expenditure","operating expenditure","perbelanjaan modal","perbelanjaan operasi"]},{"id":"subscription","g":"money","word":"Langganan","text":"Membayar secara tetap, biasanya bulanan atau tahunan, untuk terus menggunakan sesuatu.","also":["langganan","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Perisian sebagai perkhidmatan (SaaS)","text":"Perisian yang anda gunakan dalam talian dan dibayar secara langganan, manakala pembuatnya menjalankannya untuk anda.","also":["SaaS","software as a service","perisian sebagai perkhidmatan"]},{"id":"payg","g":"money","word":"Bayar mengikut guna","text":"Membayar hanya untuk apa yang anda gunakan, seperti pengkomputeran awan atau token AI.","also":["bayar mengikut guna","pay as you go","pay-as-you-go","usage-based pricing","harga berasaskan penggunaan"]},{"id":"overage","g":"money","word":"Lebihan penggunaan","text":"Penggunaan melebihi apa yang dimasukkan dalam pelan anda, yang boleh menelan kos tambahan.","also":["lebihan penggunaan","overage","overages","overage charges","caj lebihan"]},{"id":"billingalert","g":"money","word":"Makluman bil","text":"Mesej apabila perbelanjaan atau penggunaan mencapai paras yang anda pilih. Ia memberi amaran, tetapi tidak selalu menghentikan caj seterusnya.","also":["makluman bil","billing alert","billing alerts","spending alert","makluman perbelanjaan"]},{"id":"freetier","g":"money","word":"Peringkat percuma","text":"Peringkat percuma bagi perkhidmatan berbayar, dengan had. Berguna untuk bermula.","also":["peringkat percuma","free tier","free plan","pelan percuma"]},{"id":"pricing","g":"money","word":"Pelan harga","text":"Pakej berbeza yang dijual oleh sesuatu perkhidmatan, masing-masing dengan harga dan hadnya sendiri.","also":["pelan harga","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Lesen","text":"Peraturan tentang bagaimana anda boleh menggunakan, menyalin, mengubah atau berkongsi sesuatu yang dibuat orang lain, seperti perisian, fon atau gambar.","also":["lesen","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Sumber terbuka","text":"Perisian yang kodnya boleh dibaca, digunakan dan selalunya diubah oleh sesiapa sahaja secara percuma, di bawah peraturan lesennya.","also":["sumber terbuka","open source","open-source","open source software","OSS","perisian sumber terbuka"]},{"id":"osslicence","g":"money","word":"Lesen sumber terbuka","text":"Peraturan yang disertakan dengan kod sumber terbuka. Sesetengahnya membenarkan hampir apa sahaja (seperti MIT); sesetengahnya meminta anda berkongsi perubahan anda juga (seperti GPL).","also":["lesen sumber terbuka","open source licence","open source licences","MIT licence","GPL","lesen MIT"]},{"id":"proprietary","g":"money","word":"Proprietari","text":"Dimiliki oleh sebuah syarikat dan tidak bebas disalin atau diubah. Bertentangan dengan sumber terbuka.","also":["proprietari","proprietary","proprietary software","perisian proprietari"]},{"id":"copyright","g":"money","word":"Hak cipta","text":"Hak undang-undang pencipta untuk mengawal salinan karyanya, termasuk kod dan tulisan.","also":["hak cipta","copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Harta intelek (IP)","text":"Idea dan ciptaan yang dianggap undang-undang sebagai milik seseorang, seperti kod, reka bentuk, nama dan logo.","also":["harta intelek","intellectual property","IP"]},{"id":"tos","g":"money","word":"Syarat perkhidmatan","text":"Peraturan yang anda setujui apabila menggunakan sesuatu perkhidmatan.","also":["syarat perkhidmatan","terms of service","terms and conditions","terms of use","terma dan syarat","syarat penggunaan"]},{"id":"contract","g":"money","word":"Kontrak","text":"Perjanjian bertulis antara dua pihak yang disokong oleh undang-undang.","also":["kontrak","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Penyata kerja (SOW)","text":"Dokumen yang menyatakan dengan tepat kerja apa yang akan dibuat, bila siap dan berapa harganya.","also":["SOW","statement of work","penyata kerja"]},{"id":"fixedprice","g":"money","word":"Harga tetap","text":"Harga yang dipersetujui untuk keseluruhan kerja, tidak kira berapa lama ia mengambil masa.","also":["harga tetap","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Masa dan bahan","text":"Membayar untuk jam yang benar-benar dikerjakan dan barang yang benar-benar digunakan, bukannya harga tetap.","also":["masa dan bahan","time and materials","T&M"]},{"id":"invoice","g":"money","word":"Invois","text":"Bil yang meminta bayaran untuk kerja yang dibuat atau barang yang dibekalkan.","also":["invois","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Penguncian vendor","text":"Apabila berpindah daripada pembekal terlalu sukar atau mahal sehingga anda terperangkap dengan mereka.","also":["penguncian vendor","vendor lock-in","lock-in","terkunci pada vendor"]},{"id":"procurement","g":"money","word":"Perolehan","text":"Proses memilih dan membeli daripada pembekal.","also":["perolehan","pemerolehan","procurement"]},{"id":"servicecredit","g":"money","word":"Kredit perkhidmatan","text":"Wang dikembalikan atau diskaun yang anda dapat apabila pembekal gagal memenuhi SLA-nya.","also":["kredit perkhidmatan","service credit","service credits"]}]}};
